describe( 'Object3D hierarchy and events', () => {

	test( 'adds one or several objects and dispatches the hierarchy events', () => {

		const root = new Object3D();
		const first = new Object3D();
		const second = new Object3D();
		const childAdded = [];
		const addedTargets = [];

		root.addEventListener( 'childadded', event => childAdded.push( event.child ) );
		first.addEventListener( 'added', event => addedTargets.push( [ event.type, event.target ] ) );

		expect( root.add( first, second ) ).toBe( root );

		expect( root.children ).toEqual( [ first, second ] );
		expect( first.parent ).toBe( root );
		expect( second.parent ).toBe( root );
		expect( childAdded ).toEqual( [ first, second ] );
		expect( addedTargets ).toHaveLength( 1 );
		expect( addedTargets[ 0 ][ 0 ] ).toBe( 'added' );
		expect( addedTargets[ 0 ][ 1 ] ).toBe( first );

	} );

	test( 'reparents an object by removing it from its previous parent first', () => {

		const oldParent = new Object3D();
		const newParent = new Object3D();
		const child = new Object3D();
		const events = [];

		oldParent.add( child );
		child.addEventListener( 'removed', () => events.push( 'removed' ) );
		child.addEventListener( 'added', () => events.push( 'added' ) );
		oldParent.addEventListener( 'childremoved', event => events.push( `old:${ event.child === child }` ) );
		newParent.addEventListener( 'childadded', event => events.push( `new:${ event.child === child }` ) );

		newParent.add( child );

		expect( child.parent ).toBe( newParent );
		expect( oldParent.children ).toEqual( [] );
		expect( newParent.children ).toEqual( [ child ] );
		expect( events ).toEqual( [ 'removed', 'old:true', 'added', 'new:true' ] );

	} );

	test( 'rejects self and non-Object3D children without changing the hierarchy', () => {

		const root = new Object3D();
		const consoleError = jest.spyOn( console, 'error' ).mockImplementation( () => {} );

		expect( root.add( root ) ).toBe( root );
		expect( root.add( {} ) ).toBe( root );
		expect( root.add( null ) ).toBe( root );

		expect( root.children ).toEqual( [] );
		expect( root.parent ).toBeNull();
		expect( consoleError ).toHaveBeenCalledTimes( 3 );
		expect( consoleError.mock.calls[ 0 ][ 0 ] ).toContain( 'Object3D.add' );

	} );

	test( 'removes one or several children and dispatches removal events', () => {

		const root = new Object3D();
		const first = new Object3D();
		const second = new Object3D();
		const third = new Object3D();
		const removed = [];

		root.add( first, second, third );
		first.addEventListener( 'removed', event => removed.push( event.target ) );
		root.addEventListener( 'childremoved', event => removed.push( event.child ) );

		expect( root.remove( first, second ) ).toBe( root );
		expect( root.children ).toEqual( [ third ] );
		expect( first.parent ).toBeNull();
		expect( second.parent ).toBeNull();
		expect( removed ).toEqual( [ first, first, second, second ] );

		const eventCount = removed.length;
		expect( root.remove( new Object3D() ) ).toBe( root );
		expect( removed ).toHaveLength( eventCount );

	} );

	test( 'removeFromParent and clear detach objects and return this', () => {

		const root = new Object3D();
		const first = new Object3D();
		const second = new Object3D();
		const removed = [];

		root.add( first, second );
		root.addEventListener( 'childremoved', event => removed.push( event.child ) );

		expect( first.removeFromParent() ).toBe( first );
		expect( first.parent ).toBeNull();
		expect( root.children ).toEqual( [ second ] );

		expect( root.clear() ).toBe( root );
		expect( root.children ).toEqual( [] );
		expect( second.parent ).toBeNull();
		expect( removed ).toEqual( [ first, second ] );

		expect( first.removeFromParent() ).toBe( first );
		expect( removed ).toEqual( [ first, second ] );

	} );

	test( 'attach preserves world transforms while reparenting', () => {

		const oldParent = new Object3D();
		const newParent = new Object3D();
		const child = new Object3D();
		const worldPosition = new Vector3();
		const events = [];

		oldParent.position.set( 1, 0, 0 );
		child.position.set( 2, 5, 1 );
		oldParent.add( child );
		newParent.position.set( 10, 0, 0 );
		newParent.updateWorldMatrix( true, false );
		child.getWorldPosition( worldPosition );

		newParent.addEventListener( 'childadded', event => events.push( event.child ) );

		expect( newParent.attach( child ) ).toBe( newParent );

		expect( child.parent ).toBe( newParent );
		expect( oldParent.children ).toEqual( [] );
		expect( newParent.children ).toEqual( [ child ] );
		expectVectorClose( child.getWorldPosition( new Vector3() ), worldPosition );
		expectVectorClose( child.position, new Vector3( - 7, 5, 1 ) );
		expect( events ).toEqual( [ child ] );

	} );

} );

describe( 'Object3D hierarchy queries and traversal', () => {

	function makeTree() {

		const root = new Object3D();
		const branch = new Object3D();
		const leaf = new Object3D();
		const sibling = new Object3D();

		root.name = 'root';
		branch.name = 'branch';
		leaf.name = 'leaf';
		sibling.name = 'sibling';

		root.add( branch, sibling );
		branch.add( leaf );

		return { root, branch, leaf, sibling };

	}

	test( 'finds itself or the first matching descendant by id, name, or property', () => {

		const { root, branch, leaf } = makeTree();

		expect( root.getObjectById( root.id ) ).toBe( root );
		expect( root.getObjectById( leaf.id ) ).toBe( leaf );
		expect( root.getObjectById( - 1 ) ).toBeUndefined();

		expect( root.getObjectByName( 'root' ) ).toBe( root );
		expect( root.getObjectByName( 'leaf' ) ).toBe( leaf );
		expect( root.getObjectByName( 'missing' ) ).toBeUndefined();

		branch.userData.role = 'branch';
		leaf.userData.role = 'leaf';
		expect( root.getObjectByProperty( 'name', 'branch' ) ).toBe( branch );
		expect( root.getObjectByProperty( 'missing', true ) ).toBeUndefined();

	} );

	test( 'collects every matching object depth-first into the supplied result array', () => {

		const { root, branch, leaf, sibling } = makeTree();
		const result = [ 'existing' ];

		branch.visible = false;
		sibling.visible = false;

		expect( root.getObjectsByProperty( 'visible', false ) ).toEqual( [ branch, sibling ] );
		const returned = root.getObjectsByProperty( 'visible', false, result );

		expect( returned ).toBe( result );
		expect( result ).toEqual( [ 'existing', branch, sibling ] );
		expect( root.getObjectsByProperty( 'name', 'leaf' ) ).toEqual( [ leaf ] );

	} );

	test( 'traverse visits the root and descendants depth-first', () => {

		const { root, branch, leaf, sibling } = makeTree();
		const visited = [];

		root.traverse( object => visited.push( object.name ) );

		expect( visited ).toEqual( [ 'root', 'branch', 'leaf', 'sibling' ] );

	} );

	test( 'traverseVisible skips invisible objects and their descendants', () => {

		const { root, branch, sibling } = makeTree();
		const visited = [];

		branch.visible = false;
		root.traverseVisible( object => visited.push( object.name ) );

		expect( visited ).toEqual( [ 'root', 'sibling' ] );

	} );

	test( 'traverseAncestors visits parent, grandparent, and stops at the root', () => {

		const { root, branch, leaf } = makeTree();
		const visited = [];

		leaf.traverseAncestors( object => visited.push( object ) );

		expect( visited ).toEqual( [ branch, root ] );

		root.traverseAncestors( () => visited.push( new Object3D() ) );
		expect( visited ).toHaveLength( 2 );

	} );

} );

