describe( 'Object3D hierarchy queries and traversal', () => {

	function makeTree() {

		const root = new Object3D();
		const branch = new Object3D();
		const leaf = new Object3D();
		const sibling = new Object3D();

		root.name = 'root';
		branch.name = 'branch';
		leaf.name = 'leaf';
		sibling.name = 'sibling';

		root.add( branch, sibling );
		branch.add( leaf );

		return { root, branch, leaf, sibling };

	}

	test( 'finds itself or the first matching descendant by id, name, or property', () => {

		const { root, branch, leaf } = makeTree();

		expect( root.getObjectById( root.id ) ).toBe( root );
		expect( root.getObjectById( leaf.id ) ).toBe( leaf );
		expect( root.getObjectById( - 1 ) ).toBeUndefined();

		expect( root.getObjectByName( 'root' ) ).toBe( root );
		expect( root.getObjectByName( 'leaf' ) ).toBe( leaf );
		expect( root.getObjectByName( 'missing' ) ).toBeUndefined();

		branch.userData.role = 'branch';
		leaf.userData.role = 'leaf';
		expect( root.getObjectByProperty( 'name', 'branch' ) ).toBe( branch );
		expect( root.getObjectByProperty( 'missing', true ) ).toBeUndefined();

	} );

	test( 'collects every matching object depth-first into the supplied result array', () => {

		const { root, branch, leaf, sibling } = makeTree();
		const result = [ 'existing' ];

		branch.visible = false;
		sibling.visible = false;

		expect( root.getObjectsByProperty( 'visible', false ) ).toEqual( [ branch, sibling ] );
		const returned = root.getObjectsByProperty( 'visible', false, result );

		expect( returned ).toBe( result );
		expect( result ).toEqual( [ 'existing', branch, sibling ] );
		expect( root.getObjectsByProperty( 'name', 'leaf' ) ).toEqual( [ leaf ] );

	} );

	test( 'traverse visits the root and descendants depth-first', () => {

		const { root, branch, leaf, sibling } = makeTree();
		const visited = [];

		root.traverse( object => visited.push( object.name ) );

		expect( visited ).toEqual( [ 'root', 'branch', 'leaf', 'sibling' ] );

	} );

	test( 'traverseVisible skips invisible objects and their descendants', () => {

		const { root, branch, sibling } = makeTree();
		const visited = [];

		branch.visible = false;
		root.traverseVisible( object => visited.push( object.name ) );

		expect( visited ).toEqual( [ 'root', 'sibling' ] );

	} );

	test( 'traverseAncestors visits parent, grandparent, and stops at the root', () => {

		const { root, branch, leaf } = makeTree();
		const visited = [];

		leaf.traverseAncestors( object => visited.push( object ) );

		expect( visited ).toEqual( [ branch, root ] );

		root.traverseAncestors( () => visited.push( new Object3D() ) );
		expect( visited ).toHaveLength( 2 );

	} );

} );

