@param path - A Windows backslash path.
@returns A path with forward slashes.

@example
```
import * as path from 'path';
import slash = require('slash');

const string = path.join('foo', 'bar');
// Unix    => foo/bar
// Windows => foo\\bar

slash(string);
// Unix    => foo/bar
