describe( 'PropertyBinding failure signaling', () => {

	let messages;
	let previousConsoleFunction;

	beforeEach( () => {

		messages = [];
		previousConsoleFunction = getConsoleFunction();
		setConsoleFunction( ( type, message, ...params ) => {

			messages.push( { type, message, params } );

		} );

	} );

	afterEach( () => {

		setConsoleFunction( previousConsoleFunction );

	} );

	function expectOnlyMessage( type, message ) {

		expect( messages ).toHaveLength( 1 );
		expect( messages[ 0 ].type ).toBe( type );
		expect( messages[ 0 ].message ).toBe( message );

	}

	it( 'warns and becomes a no-op when the target node is missing', () => {

		const root = new Object3D();
		const binding = new PropertyBinding( root, 'missing.position' );
		const output = [ 7 ];

		binding.getValue( output, 0 );
		binding.setValue( [ 3 ], 0 );

		expect( output ).toEqual( [ 7 ] );
		expectOnlyMessage( 'warn', 'THREE.PropertyBinding: No target node found for track: missing.position.' );

	} );

	it( 'errors and becomes a no-op when the target property is missing', () => {

		const root = new Object3D();
		root.name = 'node';
		const binding = new PropertyBinding( root, 'node.doesNotExist' );
		const output = [ 6 ];

		binding.getValue( output, 0 );
		binding.setValue( [ 2 ], 0 );

		expect( output ).toEqual( [ 6 ] );
		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Trying to update property for track: node.doesNotExist but it wasn\'t found.'
		);

	} );

	it( 'errors when a materials path targets a node without a material', () => {

		const root = { name: 'node' };
		const binding = new PropertyBinding( root, 'node.materials[0].opacity' );

		binding.bind();

		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Can not bind to material as node does not have a material.'
		);

	} );

	it( 'errors when a material has no materials array', () => {

		const root = { name: 'node', material: { opacity: 1 } };
		const binding = new PropertyBinding( root, 'node.materials[0].opacity' );

		binding.bind();

		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Can not bind to material.materials as node.material does not have a materials array.'
		);

	} );

	it( 'errors when a bones path targets a node without a skeleton', () => {

		const root = { name: 'node' };
		const binding = new PropertyBinding( root, 'node.bones[0].position' );

		binding.bind();

		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Can not bind to bones as node does not have a skeleton.'
		);

	} );

	it( 'errors when a map path targets a node without a material', () => {

		const root = { name: 'node' };
		const binding = new PropertyBinding( root, 'node.map.offset' );

		binding.bind();

		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Can not bind to material as node does not have a material.'
		);

	} );

	it( 'errors when a material map is absent', () => {

		const root = { name: 'node', material: {} };
		const binding = new PropertyBinding( root, 'node.map.offset' );

		binding.bind();

		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Can not bind to material.map as node.material does not have a map.'
		);

	} );

	it( 'errors when an object index does not exist', () => {

		const root = {
			name: 'node',
			material: { materials: [ new MeshBasicMaterial() ] }
		};
		const binding = new PropertyBinding( root, 'node.materials[1].opacity' );

		binding.bind();

		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Trying to bind to objectIndex of objectName, but is undefined.'
		);

	} );

	it( 'errors for a supplied parsed path whose object name is absent', () => {

		const root = { name: 'node' };
		const binding = new PropertyBinding( root, 'custom', {
			nodeName: 'node',
			objectName: 'custom',
			propertyName: 'value'
		} );

		binding.bind();

		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Can not bind to objectName of node undefined.'
		);

	} );

	it( 'errors when a morph-target influence is bound without geometry', () => {

		const root = { morphTargetInfluences: [ 0 ] };
		const binding = new PropertyBinding( root, '.morphTargetInfluences[smile]' );

		binding.bind();

		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Can not bind to morphTargetInfluences because node does not have a geometry.'
		);

	} );

	it( 'errors when morph-target influences are bound without morph attributes', () => {

		const root = { geometry: {}, morphTargetInfluences: [ 0 ] };
		const binding = new PropertyBinding( root, '.morphTargetInfluences[smile]' );

		binding.bind();

		expectOnlyMessage(
			'error',
			'THREE.PropertyBinding: Can not bind to morphTargetInfluences because node does not have a geometry.morphAttributes.'
		);

	} );

} );

describe( 'PropertyBinding.Composite with AnimationObjectGroup', () => {

	it( 'reads the first active object and writes to every active object as the group changes', () => {

		const first = new Object3D();
		const second = new Object3D();
		first.weight = 1;
		second.weight = 2;
		const group = new AnimationObjectGroup( first, second );
		const composite = PropertyBinding.create( group, '.weight' );

		expect( composite ).toBeInstanceOf( PropertyBinding.Composite );

		let output = [];
		composite.getValue( output, 0 );
		expect( output ).toEqual( [ 1 ] );

		composite.setValue( [ 5 ], 0 );
		expect( first.weight ).toBe( 5 );
		expect( second.weight ).toBe( 5 );

		first.weight = 7;
		output = [];
		composite.getValue( output, 0 );
		expect( output ).toEqual( [ 7 ] );

		group.remove( first );
		output = [];
		composite.getValue( output, 0 );
		expect( output ).toEqual( [ 5 ] );

		composite.setValue( [ 6 ], 0 );
		expect( first.weight ).toBe( 7 );
		expect( second.weight ).toBe( 6 );

		const third = new Object3D();
		third.weight = 3;
		group.add( third );

		composite.setValue( [ 8 ], 0 );
		expect( second.weight ).toBe( 8 );
		expect( third.weight ).toBe( 8 );

		output = [];
		composite.getValue( output, 0 );
		expect( output ).toEqual( [ 8 ] );

	} );

} );
