describe( 'Material disposal', () => {

	test( 'dispose dispatches a dispose event with the material as its target', () => {

		const material = new Material();
		let observedTarget;
		const listener = jest.fn( event => {

			observedTarget = event.target;

		} );

		material.addEventListener( 'dispose', listener );

