import { Skeleton } from '../../src/objects/Skeleton.js';
import { Shape } from '../../src/extras/core/Shape.js';
import { Matrix4 } from '../../src/math/Matrix4.js';
import { Texture } from '../../src/textures/Texture.js';
import { TextureSource } from '../../src/textures/TextureSource.js';
import { SphericalHarmonics3 } from '../../src/math/SphericalHarmonics3.js';
import {
	RGBAFormat,
	UnsignedByteType,
	EquirectangularReflectionMapping,
	RepeatWrapping,
	MirroredRepeatWrapping,
	LinearMipmapLinearFilter,
	NearestFilter,
	LessEqualCompare,
	DetachedBindMode
} from '../../src/constants.js';

function makeJSON( object, extra = {} ) {

	return {
		metadata: { version: 4.7, type: 'Object' },
		object,
		...extra
	};

}

function toDataURI( value ) {

	return 'data:application/json,' + encodeURIComponent( JSON.stringify( value ) );

}

function embeddedImage( uuid = 'image', width = 1, height = 1 ) {

	return {
		uuid,
		url: {
			type: 'Uint8Array',
			data: [ 255, 0, 0, 255 ],
			width,
			height
		}
	};

}

let originalHTMLImageElement;

beforeAll( () => {

	originalHTMLImageElement = Object.getOwnPropertyDescriptor( globalThis, 'HTMLImageElement' );

	if ( globalThis.HTMLImageElement === undefined ) {

		globalThis.HTMLImageElement = class HTMLImageElement {};

	}

} );

afterAll( () => {

	if ( originalHTMLImageElement === undefined ) {

		delete globalThis.HTMLImageElement;

	} else {

		Object.defineProperty( globalThis, 'HTMLImageElement', originalHTMLImageElement );

	}

} );

afterEach( () => {

	jest.restoreAllMocks();

} );

describe( 'ObjectLoader construction', () => {

	test( 'uses the supplied loading manager', () => {

		const manager = new LoadingManager();
		const loader = new ObjectLoader( manager );

		expect( loader ).toBeInstanceOf( ObjectLoader );
		expect( loader.manager ).toBe( manager );
		expect( loader.resourcePath ).toBe( '' );

	} );

} );

describe( 'ObjectLoader.parse and parseAsync', () => {

	test( 'parse returns the parsed object and reports it synchronously when no images are loaded', () => {

		const loader = new ObjectLoader();
		const onLoad = jest.fn();
		const json = makeJSON( {
			uuid: 'root',
			type: 'Group',
			name: 'Root',
			children: [
				{ uuid: 'child', type: 'Object3D', name: 'Child' }
			]
		} );

		const result = loader.parse( json, onLoad );

		expect( result ).toBeInstanceOf( Group );
		expect( result.uuid ).toBe( 'root' );
		expect( result.name ).toBe( 'Root' );
		expect( result.getObjectByProperty( 'uuid', 'child' ).name ).toBe( 'Child' );
		expect( onLoad ).toHaveBeenCalledTimes( 1 );
		expect( onLoad ).toHaveBeenCalledWith( result );

	} );

	test( 'parse reports the finished object when only embedded image data exists', () => {

		const loader = new ObjectLoader();
		const onLoad = jest.fn();
		const json = makeJSON( {
			uuid: 'root',
			type: 'Scene',
			background: 'texture',
			children: []
		}, {
			images: [ embeddedImage( 'image' ) ],
			textures: [ { uuid: 'texture', image: 'image' } ]
		} );

		const result = loader.parse( json, onLoad );

		expect( result.background.isTexture ).toBe( true );
		expect( result.background.uuid ).toBe( 'texture' );
		expect( onLoad ).toHaveBeenCalledTimes( 1 );
		expect( onLoad ).toHaveBeenCalledWith( result );

	} );

	test( 'parseAsync resolves with the parsed object', async () => {

		const loader = new ObjectLoader();
		const json = makeJSON( {
			uuid: 'root',
			type: 'Mesh',
			name: 'Async mesh'
		}, {
			geometries: [ { uuid: 'geometry', type: 'BoxGeometry', width: 2, height: 3, depth: 4 } ],
			materials: [ { uuid: 'material', type: 'MeshBasicMaterial', color: 0x336699 } ]
		} );

		const result = await loader.parseAsync( json );

		expect( result ).toBeInstanceOf( Mesh );
		expect( result.name ).toBe( 'Async mesh' );
		expect( result.geometry ).toBeInstanceOf( BoxGeometry );
		expect( result.material.isMeshBasicMaterial ).toBe( true );
		expect( result.material.color.getHex() ).toBe( 0x336699 );

	} );

	test( 'parse resolves animations and attaches them to objects', () => {

		const loader = new ObjectLoader();
		const clipJSON = {
			name: 'Move',
			duration: 2,
			uuid: 'clip',
			blendMode: 2500,
			userData: JSON.stringify( { loop: true } ),
			tracks: [
				{
					name: 'position',
					type: 'VectorKeyframeTrack',
					times: [ 0, 2 ],
					values: [ 0, 0, 0, 1, 2, 3 ]
				}
			]
		};

		const result = loader.parse( makeJSON( {
			uuid: 'root',
			type: 'Object3D',
			animations: [ 'clip' ]
		}, { animations: [ clipJSON ] } ) );

		expect( result.animations ).toHaveLength( 1 );
		expect( result.animations[ 0 ].uuid ).toBe( 'clip' );
		expect( result.animations[ 0 ].name ).toBe( 'Move' );
		expect( result.animations[ 0 ].duration ).toBe( 2 );
		expect( result.animations[ 0 ].tracks[ 0 ].name ).toBe( 'position' );
		expect( result.animations[ 0 ].userData ).toEqual( { loop: true } );

	} );

} );

describe( 'ObjectLoader response loading', () => {

	test( 'load fetches, parses, and resolves the resource path from the URL', async () => {

		const manager = new LoadingManager();
		const uri = toDataURI( makeJSON( { uuid: 'loaded', type: 'Group' } ) );
		manager.setURLModifier( ( url ) => {

			expect( url ).toBe( 'models/scene.json' );
			return uri;

		} );
		const loader = new ObjectLoader( manager );
		const onProgress = jest.fn();

		const result = await new Promise( ( resolve, reject ) => {

			loader.load( 'models/scene.json', resolve, onProgress, reject );

		} );

		expect( result ).toBeInstanceOf( Group );
		expect( result.uuid ).toBe( 'loaded' );
		expect( loader.resourcePath ).toBe( 'models/' );

	} );

	test( 'loadAsync fetches and parses a URL', async () => {

		const loader = new ObjectLoader();
		const uri = toDataURI( makeJSON( { uuid: 'async-load', type: 'Object3D' } ) );

		const result = await loader.loadAsync( uri );

		expect( result ).toBeInstanceOf( Object3D );
		expect( result.uuid ).toBe( 'async-load' );

	} );

	test( 'load reports malformed JSON through its error callback', async () => {

		const consoleError = jest.spyOn( console, 'error' ).mockImplementation( () => {} );
		const loader = new ObjectLoader();
		const onError = jest.fn();

		await new Promise( ( resolve, reject ) => {

			loader.load( 'data:application/json,not-json', () => {

				reject( new Error( 'load should not succeed' ) );

			}, undefined, ( error ) => {

				onError( error );
				resolve();

			} );

		} );

		expect( onError ).toHaveBeenCalledTimes( 1 );
		expect( onError.mock.calls[ 0 ][ 0 ] ).toBeInstanceOf( SyntaxError );
		expect( consoleError ).toHaveBeenCalled();
		expect( consoleError.mock.calls[ 0 ].join( ' ' ) ).toContain( 'ObjectLoader: Can\'t parse' );

	} );

	test( 'load rejects geometry metadata through its error callback', async () => {

		const consoleError = jest.spyOn( console, 'error' ).mockImplementation( () => {} );
		const loader = new ObjectLoader();
		const uri = toDataURI( {
			metadata: { version: 4.7, type: 'Geometry' },
			object: { uuid: 'object', type: 'Object3D' }
		} );
		const onError = jest.fn();

		await new Promise( ( resolve, reject ) => {

			loader.load( uri, () => reject( new Error( 'load should not succeed' ) ), undefined, ( error ) => {

				onError( error );
				resolve();

			} );

		} );

		expect( onError ).toHaveBeenCalledTimes( 1 );
		expect( onError.mock.calls[ 0 ][ 0 ] ).toEqual( new Error( 'THREE.ObjectLoader: Can\'t load ' + uri ) );
		expect( consoleError ).toHaveBeenCalled();

	} );

	test( 'loadAsync rejects malformed JSON with a descriptive error', async () => {

		const loader = new ObjectLoader();

		await expect( loader.loadAsync( 'data:application/json,bad-json' ) ).rejects.toThrow( /THREE\.ObjectLoader: Can't parse/ );

	} );

	test.each( [
		[ 'missing metadata', { object: { uuid: 'object', type: 'Object3D' } } ],
		[ 'missing metadata type', { metadata: { version: 4.7 }, object: { uuid: 'object', type: 'Object3D' } } ],
		[ 'geometry metadata', { metadata: { type: 'Geometry' }, object: { uuid: 'object', type: 'Object3D' } } ]
	] )( 'loadAsync rejects %s', async ( _name, json ) => {

		const loader = new ObjectLoader();
		const uri = toDataURI( json );

		await expect( loader.loadAsync( uri ) ).rejects.toThrow( new RegExp( 'THREE\\.ObjectLoader: Can\\'t load ' + uri.replace( /[.*+?^${}()|[\]\\]/g, '\\$&' ) ) );

	} );

} );

describe( 'ObjectLoader geometry, shape, and material parsing', () => {

	test( 'parses built-in geometry parameters and applies identity fields', () => {

		const loader = new ObjectLoader();
		const geometries = loader.parseGeometries( [
			{
				uuid: 'box',
				type: 'BoxGeometry',
				width: 2,
				height: 3,
				depth: 4,
				name: 'Box',
				userData: { tag: 'cube' }
			}
		], {} );

		const geometry = geometries.box;

		expect( geometry ).toBeInstanceOf( BoxGeometry );
		expect( geometry.parameters.width ).toBe( 2 );
		expect( geometry.parameters.height ).toBe( 3 );
		expect( geometry.parameters.depth ).toBe( 4 );
		expect( geometry.uuid ).toBe( 'box' );
		expect( geometry.name ).toBe( 'Box' );
		expect( geometry.userData ).toEqual( { tag: 'cube' } );

	} );

	test( 'parses BufferGeometry JSON and typed buffer attributes', () => {

		const loader = new ObjectLoader();
		const geometries = loader.parseGeometries( [
			{
				uuid: 'buffer',
				type: 'BufferGeometry',
				data: {
					attributes: {
						position: {
							itemSize: 3,
							type: 'Float32Array',
							array: [ 0, 0, 0, 1, 0, 0, 0, 1, 0 ]
						}
					},
					index: {
						type: 'Uint16Array',
						array: [ 0, 1, 2 ]
					},
					groups: [ { start: 0, count: 3, materialIndex: 0 } ]
				}
			}
		], {} );

		const geometry = geometries.buffer;
		const position = geometry.getAttribute( 'position' );

		expect( geometry ).toBeInstanceOf( BufferGeometry );
		expect( position.itemSize ).toBe( 3 );
		expect( position.array ).toBeInstanceOf( Float32Array );
		expect( Array.from( position.array ) ).toEqual( [ 0, 0, 0, 1, 0, 0, 0, 1, 0 ] );
		expect( geometry.getIndex().array ).toBeInstanceOf( Uint16Array );
		expect( geometry.groups ).toEqual( [ { start: 0, count: 3, materialIndex: 0 } ] );

	} );

	test( 'supports geometries registered with registerGeometry', () => {

		class RegisteredGeometry {

			constructor( shapes ) {

				this.isRegisteredGeometry = true;
				this.shapes = shapes;

			}

			static fromJSON( data, shapes ) {

				return new RegisteredGeometry( { data, shapes } );

			}

		}

		ObjectLoader.registerGeometry( 'RegisteredTestGeometry', RegisteredGeometry );

		const loader = new ObjectLoader();
		const shape = new Shape();
		const shapes = { shape };
		const geometries = loader.parseGeometries( [
			{
				uuid: 'custom',
				type: 'RegisteredTestGeometry',
				name: 'Custom',
				userData: { custom: true }
			}
		], shapes );

		expect( geometries.custom ).toBeInstanceOf( RegisteredGeometry );
		expect( geometries.custom.isRegisteredGeometry ).toBe( true );
		expect( geometries.custom.shapes.shapes ).toBe( shapes );
		expect( geometries.custom.uuid ).toBe( 'custom' );
		expect( geometries.custom.name ).toBe( 'Custom' );
		expect( geometries.custom.userData ).toEqual( { custom: true } );

	} );

	test( 'parses shapes and preserves their contour', () => {

		const shape = new Shape();
		shape.moveTo( 0, 0 );
		shape.lineTo( 2, 0 );
		shape.lineTo( 2, 2 );
		shape.lineTo( 0, 2 );
		shape.lineTo( 0, 0 );
		const json = shape.toJSON();
		json.uuid = 'shape-id';

		const loader = new ObjectLoader();
		const shapes = loader.parseShapes( [ json ] );

		expect( shapes[ 'shape-id' ] ).toBeInstanceOf( Shape );
		expect( shapes[ 'shape-id' ].uuid ).toBe( 'shape-id' );
		expect( shapes[ 'shape-id' ].getPoints( 1 ) ).toHaveLength( 5 );
		expect( shapes[ 'shape-id' ].getPoints( 1 )[ 1 ].x ).toBe( 2 );

	} );

	test( 'parses materials, binds textures, and caches repeated material UUIDs', () => {

		const loader = new ObjectLoader();
		const texture = new Texture();
		const data = {
			uuid: 'material',
			type: 'MeshStandardMaterial',
			color: 0x224466,
			metalness: 0.75,
			roughness: 0.25,
			map: 'texture'
		};

		const materials = loader.parseMaterials( [ data, data ], { texture } );

		expect( materials.material.isMeshStandardMaterial ).toBe( true );
		expect( materials.material.color.getHex() ).toBe( 0x224466 );
		expect( materials.material.metalness ).toBe( 0.75 );
		expect( materials.material.roughness ).toBe( 0.25 );
		expect( materials.material.map ).toBe( texture );
		expect( loader.parseMaterials( [ data ], { texture } ).material ).toBe( materials.material );

	} );

	test( 'parses animation clips and keyframe tracks', () => {

		const loader = new ObjectLoader();
		const animations = loader.parseAnimations( [
			{
				name: 'Scale',
				duration: 1.5,
				uuid: 'animation',
				fps: 30,
				userData: '{"kind":"test"}',
				tracks: [
					{
						name: 'scale',
						type: 'VectorKeyframeTrack',
						times: [ 0, 30 ],
						values: [ 1, 1, 1, 2, 2, 2 ]
					}
				]
			}
		] );

		const clip = animations.animation;

		expect( clip.uuid ).toBe( 'animation' );
		expect( clip.name ).toBe( 'Scale' );
		expect( clip.duration ).toBe( 1.5 );
		expect( clip.userData ).toEqual( { kind: 'test' } );
		expect( clip.tracks ).toHaveLength( 1 );
		expect( clip.tracks[ 0 ].name ).toBe( 'scale' );
		expect( Array.from( clip.tracks[ 0 ].times ) ).toEqual( [ 0, 1 ] );

	} );

} );

describe( 'ObjectLoader image and texture parsing', () => {

	test( 'parses embedded single-image data into a texture source', () => {

		const loader = new ObjectLoader();
		const images = loader.parseImages( [ embeddedImage( 'image', 2, 3 ) ] );

		expect( images.image ).toBeInstanceOf( TextureSource );
		expect( images.image.data.width ).toBe( 2 );
		expect( images.image.data.height ).toBe( 3 );
		expect( images.image.data.data ).toBeInstanceOf( Uint8Array );
		expect( Array.from( images.image.data.data ) ).toEqual( [ 255, 0, 0, 255 ] );

	} );

	test( 'parseImagesAsync resolves embedded single-image data', async () => {

		const loader = new ObjectLoader();
		const images = await loader.parseImagesAsync( [ embeddedImage( 'async-image' ) ] );

		expect( images[ 'async-image' ] ).toBeInstanceOf( TextureSource );
		expect( images[ 'async-image' ].data.data ).toBeInstanceOf( Uint8Array );

	} );

	test( 'parses texture properties and texture constants', () => {

		const warn = jest.spyOn( console, 'warn' ).mockImplementation( () => {} );
		const loader = new ObjectLoader();
		const images = loader.parseImages( [ embeddedImage( 'image' ) ] );
		const textures = loader.parseTextures( [
			{
				uuid: 'texture',
				image: 'image',
				name: 'Albedo',
				mapping: 'EquirectangularReflectionMapping',
				channel: 2,
				offset: [ 0.1, 0.2 ],
				repeat: [ 2, 3 ],
				center: [ 0.4, 0.5 ],
				rotation: 0.75,
				wrap: [ 'RepeatWrapping', 'MirroredRepeatWrapping' ],
				format: RGBAFormat,
				internalFormat: 'RGBA8',
				type: UnsignedByteType,
				colorSpace: 'srgb',
				minFilter: 'LinearMipmapLinearFilter',
				magFilter: 'NearestFilter',
				anisotropy: 8,
				flipY: true,
				generateMipmaps: true,
				mipmapsAutoUpdate: false,
				premultiplyAlpha: true,
				unpackAlignment: 4,
				compareFunction: LessEqualCompare,
				normalized: true,
				userData: { label: 'albedo' }
			}
		], images );

		const texture = textures.texture;

		expect( texture.isDataTexture ).toBe( true );
		expect( texture.uuid ).toBe( 'texture' );
		expect( texture.name ).toBe( 'Albedo' );
		expect( texture.source ).toBe( images.image );
		expect( texture.mapping ).toBe( EquirectangularReflectionMapping );
		expect( texture.channel ).toBe( 2 );
		expect( Array.from( texture.offset.toArray() ) ).toEqual( [ 0.1, 0.2 ] );
		expect( Array.from( texture.repeat.toArray() ) ).toEqual( [ 2, 3 ] );
		expect( Array.from( texture.center.toArray() ) ).toEqual( [ 0.4, 0.5 ] );
		expect( texture.rotation ).toBe( 0.75 );
		expect( texture.wrapS ).toBe( RepeatWrapping );
		expect( texture.wrapT ).toBe( MirroredRepeatWrapping );
		expect( texture.format ).toBe( RGBAFormat );
		expect( texture.internalFormat ).toBe( 'RGBA8' );
		expect( texture.type ).toBe( UnsignedByteType );
		expect( texture.colorSpace ).toBe( 'srgb' );
		expect( texture.minFilter ).toBe( LinearMipmapLinearFilter );
		expect( texture.magFilter ).toBe( NearestFilter );
		expect( texture.anisotropy ).toBe( 8 );
		expect( texture.flipY ).toBe( true );
		expect( texture.generateMipmaps ).toBe( true );
		expect( texture.mipmapsAutoUpdate ).toBe( false );
		expect( texture.premultiplyAlpha ).toBe( true );
		expect( texture.unpackAlignment ).toBe( 4 );
		expect( texture.compareFunction ).toBe( LessEqualCompare );
		expect( texture.normalized ).toBe( true );
		expect( texture.userData ).toEqual( { label: 'albedo' } );
		expect( warn ).toHaveBeenCalledWith( 'ObjectLoader.parseTexture: Constant should be in numeric form.', 'EquirectangularReflectionMapping' );

	} );

	test( 'parses an embedded cube image array as a CubeTexture', () => {

		const loader = new ObjectLoader();
		const sides = [ 0, 1, 2, 3, 4, 5 ].map( ( index ) => ( {
			type: 'Uint8Array',
			data: [ index, index, index, 255 ],
			width: 1,
			height: 1
		} ) );
		const images = loader.parseImages( [ { uuid: 'cube-image', url: sides } ] );
		const textures = loader.parseTextures( [ { uuid: 'cube-texture', image: 'cube-image' } ], images );

		expect( images[ 'cube-image' ].data ).toHaveLength( 6 );
		expect( images[ 'cube-image' ].data[ 0 ].isDataTexture ).toBe( true );
		expect( textures[ 'cube-texture' ].isCubeTexture ).toBe( true );
		expect( textures[ 'cube-texture' ].image ).toHaveLength( 6 );
		expect( textures[ 'cube-texture' ].source ).toBe( images[ 'cube-image' ] );

	} );

	test( 'loads relative image URLs through ImageLoader using resourcePath', () => {

		const loadedURLs = [];
		const loadSpy = jest.spyOn( ImageLoader.prototype, 'load' ).mockImplementation( function ( url, onLoad ) {

			loadedURLs.push( url );
			const image = new globalThis.HTMLImageElement();
			image.src = url;
			queueMicrotask( () => {

				onLoad( image );
				this.manager.itemEnd( url );

			} );
			return image;

		} );
		const loader = new ObjectLoader();
		loader.setResourcePath( '/assets/' );
		const onLoad = jest.fn();
		const json = makeJSON( { uuid: 'root', type: 'Scene' }, {
			images: [ { uuid: 'image', url: 'texture.png' } ],
			textures: [ { uuid: 'texture', image: 'image' } ]
		} );

		const result = loader.parse( json, onLoad );

		await new Promise( ( resolve ) => setTimeout( resolve, 0 ) );

		expect( loadSpy ).toHaveBeenCalledTimes( 1 );
		expect( loadedURLs ).toEqual( [ '/assets/texture.png' ] );
		expect( result.background ).toBeUndefined();
		expect( onLoad ).toHaveBeenCalledWith( result );

	} );

	test( 'loads relative image URLs in parseAsync through ImageLoader.loadAsync', async () => {

		const loadAsyncSpy = jest.spyOn( ImageLoader.prototype, 'loadAsync' ).mockImplementation( async ( url ) => {

			const image = new globalThis.HTMLImageElement();
			image.src = url;
			return image;

		} );
		const loader = new ObjectLoader();
		loader.setResourcePath( 'textures/' );
		const json = makeJSON( { uuid: 'root', type: 'Scene', background: 'texture' }, {
			images: [ { uuid: 'image', url: 'sky.png' } ],
			textures: [ { uuid: 'texture', image: 'image' } ]
		} );

		const result = await loader.parseAsync( json );

		expect( loadAsyncSpy ).toHaveBeenCalledWith( 'textures/sky.png' );
		expect( result.background ).toBeInstanceOf( Texture );
		expect( result.background.source.data ).toBeInstanceOf( globalThis.HTMLImageElement );

	} );

} );

describe( 'ObjectLoader object deserialization', () => {

	test( 'parses scene background, environment, fog, and scene-specific settings', () => {

		const loader = new ObjectLoader();
		const environment = new Texture();
		const scene = loader.parseObject( {
			uuid: 'scene',
			type: 'Scene',
			background: 0x00ff00,
			environment: 'environment',
			fog: { type: 'Fog', color: 0x102030, near: 1, far: 100, name: 'Haze' },
			backgroundBlurriness: 0.2,
			backgroundIntensity: 0.7,
			backgroundRotation: [ 0.1, 0.2, 0.3 ],
			environmentIntensity: 0.8,
			environmentRotation: [ 0.4, 0.5, 0.6 ]
		}, {}, {}, { environment }, {} );

		expect( scene.background.getHex() ).toBe( 0x00ff00 );
		expect( scene.environment ).toBe( environment );
		expect( scene.fog.isFog ).toBe( true );
		expect( scene.fog.name ).toBe( 'Haze' );
		expect( scene.backgroundBlurriness ).toBe( 0.2 );
		expect( scene.backgroundIntensity ).toBe( 0.7 );
		expect( Array.from( scene.backgroundRotation.toArray() ) ).toEqual( [ 0.1, 0.2, 0.3 ] );
		expect( scene.environmentIntensity ).toBe( 0.8 );
		expect( Array.from( scene.environmentRotation.toArray() ) ).toEqual( [ 0.4, 0.5, 0.6 ] );

		const fogScene = loader.parseObject( {
			type: 'Scene',
			fog: { type: 'FogExp2', color: 0x445566, density: 0.02, name: 'Dense' }
		}, {}, {}, {}, {} );

		expect( fogScene.fog.isFogExp2 ).toBe( true );
		expect( fogScene.fog.density ).toBe( 0.02 );
		expect( fogScene.fog.name ).toBe( 'Dense' );

	} );

	test( 'parses perspective and orthographic camera settings', () => {

		const loader = new ObjectLoader();
		const perspective = loader.parseObject( {
			type: 'PerspectiveCamera',
			fov: 60,
			aspect: 1.5,
			near: 0.1,
			far: 200,
			focus: 10,
			zoom: 1.2,
			filmGauge: 40,
			filmOffset: 2,
			view: { enabled: true, fullWidth: 100 }
		}, {}, {}, {}, {} );

		const orthographic = loader.parseObject( {
			type: 'OrthographicCamera',
			left: -2,
			right: 2,
			top: 3,
			bottom: -3,
			near: 0.5,
			far: 50,
			zoom: 2,
			view: { enabled: false }
		}, {}, {}, {}, {} );

		expect( perspective.isPerspectiveCamera ).toBe( true );
		expect( perspective.fov ).toBe( 60 );
		expect( perspective.aspect ).toBe( 1.5 );
		expect( perspective.near ).toBe( 0.1 );
		expect( perspective.far ).toBe( 200 );
