		const loader = new ObjectLoader();

		await expect( loader.loadAsync( 'data:application/json,bad-json' ) ).rejects.toThrow( /THREE\.ObjectLoader: Can't parse/ );

	} );

	test.each( [
		[ 'missing metadata', { object: { uuid: 'object', type: 'Object3D' } } ],
		[ 'missing metadata type', { metadata: { version: 4.7 }, object: { uuid: 'object', type: 'Object3D' } } ],
		[ 'geometry metadata', { metadata: { type: 'Geometry' }, object: { uuid: 'object', type: 'Object3D' } } ]
	] )( 'loadAsync rejects %s', async ( _name, json ) => {

		const loader = new ObjectLoader();
		const uri = toDataURI( json );

