	test( 'creates skeletons from bones and binds SkinnedMesh instances', () => {

		const loader = new ObjectLoader();
		const boneUUID = 'bone';
		const skeletonUUID = 'skeleton';
		const identity = new Matrix4().identity().toArray();
		const json = makeJSON( {
			uuid: 'root',
			type: 'Group',
			children: [
				{ uuid: boneUUID, type: 'Bone' },
				{
					uuid: 'mesh',
					type: 'SkinnedMesh',
					geometry: 'geometry',
					material: 'material',
					skeleton: skeletonUUID,
					bindMatrix: identity
				}
			]
		}, {
			geometries: [ { uuid: 'geometry', type: 'BoxGeometry', width: 1, height: 1, depth: 1 } ],
			materials: [ { uuid: 'material', type: 'MeshBasicMaterial' } ],
			skeletons: [ { uuid: skeletonUUID, bones: [ boneUUID ], boneInverses: [ identity ] } ]
		} );

		const root = loader.parse( json );
		const bone = root.getObjectByProperty( 'uuid', boneUUID );
		const mesh = root.getObjectByProperty( 'uuid', 'mesh' );

		expect( bone ).toBeInstanceOf( Bone );
		expect( mesh ).toBeInstanceOf( SkinnedMesh );
		expect( mesh.skeleton ).toBeInstanceOf( Skeleton );
		expect( mesh.skeleton.uuid ).toBe( skeletonUUID );
		expect( mesh.skeleton.bones ).toEqual( [ bone ] );
		expect( mesh.skeleton.boneInverses[ 0 ].elements ).toEqual( identity );

	} );

	test( 'warns when a SkinnedMesh refers to an unknown skeleton', () => {

		const warn = jest.spyOn( console, 'warn' ).mockImplementation( () => {} );
		const loader = new ObjectLoader();
		const mesh = new SkinnedMesh();
		mesh.skeleton = 'missing';
		const root = new Group();
		root.add( mesh );

		loader.bindSkeletons( root, { known: new Skeleton() } );

		expect( warn ).toHaveBeenCalledWith( 'ObjectLoader: No skeleton found with UUID:', 'missing' );

	} );

	test( 'resolves light targets to objects in the scene and creates a fallback otherwise', () => {

		const loader = new ObjectLoader();
		const root = new Group();
		const target = new Object3D();
		target.uuid = 'target';
		const directional = new Object3D();
		directional.isDirectionalLight = true;
		directional.target = 'target';
		const spot = new Object3D();
		spot.isSpotLight = true;
		spot.target = 'missing';
		root.add( target, directional, spot );

		loader.bindLightTargets( root );

		expect( directional.target ).toBe( target );
		expect( spot.target ).toBeInstanceOf( Object3D );
		expect( spot.target ).not.toBe( target );
		expect( spot.target.uuid ).not.toBe( 'target' );

	} );

} );
