import { BatchedMesh } from '../../../../src/objects/BatchedMesh.js';
import { InstancedMesh } from '../../../../src/objects/InstancedMesh.js';
import { Mesh } from '../../../../src/objects/Mesh.js';
import { Sprite } from '../../../../src/objects/Sprite.js';
import { Scene } from '../../../../src/scenes/Scene.js';
import { DataTexture } from '../../../../src/textures/DataTexture.js';
import { Texture } from '../../../../src/textures/Texture.js';

/**
 * Creates a minimal renderer stand-in that only implements the parts of the
 * renderer interface the observer depends on. The returned `state` object can
 * be mutated to simulate render target switches.
 */
function createRenderer( { mrt = null, renderTarget = null, outputRenderTarget = null, canvasTarget = { isCanvasTarget: true } } = {} ) {

	const state = { mrt, renderTarget, outputRenderTarget, canvasTarget };

	return {
		state,
		getMRT: () => state.mrt,
		getRenderTarget: () => state.renderTarget,
		getOutputRenderTarget: () => state.outputRenderTarget,
		getCanvasTarget: () => state.canvasTarget
	};

}

/**
 * Creates a lights node stand-in. The lights can be exchanged at runtime.
 */
function createLightsNode( lights = [] ) {

	return {
		lights,
		getBuiltinLights() {

			return this.lights;

		}
	};

}

/**
 * Creates a render object stand-in with the fields the observer reads.
 */
function createRenderObject( options = {} ) {

	const object = options.object !== undefined ? options.object : new Mesh( options.geometry, options.material );
	const material = options.material !== undefined ? options.material : object.material;
	const geometry = options.geometry !== undefined ? options.geometry : object.geometry;

	return {
		object,
		material,
		geometry,
		scene: options.scene !== undefined ? options.scene : new Scene(),
		renderer: options.renderer !== undefined ? options.renderer : createRenderer(),
		lightsNode: options.lightsNode !== undefined ? options.lightsNode : createLightsNode(),
		bundle: options.bundle !== undefined ? options.bundle : null,
		context: { width: options.width !== undefined ? options.width : 800, height: options.height !== undefined ? options.height : 600 }
	};

}

/**
 * Creates a node builder stand-in for the observer constructor.
 */
function createBuilder( { material = new Material(), scene = new Scene(), context = {}, object = new Mesh() } = {} ) {

	return { material, scene, context, object };

}

function createObserver( builder = createBuilder() ) {

	return new NodeMaterialObserver( builder );

}

function createNodeFrame( renderer, renderId ) {

	return { renderId, renderer };

}

describe( 'NodeMaterialObserver', () => {

	describe( 'constructor', () => {

		it( 'initializes the monitoring state for a builder without nodes', () => {

			const observer = createObserver();

			expect( observer.renderObjects ).toBeInstanceOf( WeakMap );
			expect( observer.hasNode ).toBe( false );
			expect( observer.hasAnimation ).toBe( false );
			expect( observer.renderId ).toBe( 0 );
			expect( Array.isArray( observer.refreshUniforms ) ).toBe( true );
			expect( observer.refreshUniforms ).toContain( 'color' );
			expect( observer.refreshUniforms ).toContain( 'map' );
			expect( observer.refreshUniforms ).toContain( 'opacity' );
			expect( observer.refreshUniforms ).toContain( 'wireframe' );
			expect( observer.refreshUniforms ).not.toContain( '_renderId' );

		} );

		it( 'detects whether the material uses node properties', () => {

			const material = new Material();
			material.colorNode = { isNode: true };

			expect( createObserver( createBuilder( { material } ) ).hasNode ).toBe( true );

		} );

		it( 'ignores falsy material node properties', () => {

			const material = new Material();
			material.colorNode = null;

			expect( createObserver( createBuilder( { material } ) ).hasNode ).toBe( false );

		} );

		it( 'detects node usage in the builder context', () => {

			const contextKeys = [ 'modelViewMatrix', 'modelNormalViewMatrix', 'getAO', 'getShadow', 'getGI' ];

			for ( const key of contextKeys ) {

				const builder = createBuilder( { context: { [ key ]: {} } } );

				expect( createObserver( builder ).hasNode ).toBe( true );

			}

		} );

		it( 'detects fog and environment nodes of the scene', () => {

			const material = new MeshBasicMaterial();
			const scene = new Scene();

			scene.fogNode = { isNode: true };
			expect( createObserver( createBuilder( { material, scene } ) ).hasNode ).toBe( true );

			// fog must be enabled on the material
			material.fog = false;
			expect( createObserver( createBuilder( { material, scene } ) ).hasNode ).toBe( false );

			const sceneWithEnvironment = new Scene();
			sceneWithEnvironment.environmentNode = { isNode: true };
			expect( createObserver( createBuilder( { material: new Material(), scene: sceneWithEnvironment } ) ).hasNode ).toBe( true );

		} );

		it( 'sets the animation flag for skinned meshes', () => {

			const object = new Mesh();
			object.isSkinnedMesh = true;

			expect( createObserver( createBuilder( { object } ) ).hasAnimation ).toBe( true );
			expect( createObserver().hasAnimation ).toBe( false );

		} );

	} );

	describe( 'containsNode', () => {

		it( 'returns false for a plain builder', () => {

			const observer = createObserver();

			expect( observer.containsNode( createBuilder() ) ).toBe( false );

		} );

		it( 'returns true if a material property is a node', () => {

			const observer = createObserver();
			const material = new Material();
			material.roughnessNode = { isNode: true };

			expect( observer.containsNode( createBuilder( { material } ) ) ).toBe( true );

		} );

		it( 'returns true if the scene has an environment node', () => {

			const observer = createObserver();
			const scene = new Scene();
			scene.environmentNode = { isNode: true };

			expect( observer.containsNode( createBuilder( { scene } ) ) ).toBe( true );

		} );

		it( 'returns false if the scene has a non node environment', () => {

			const observer = createObserver();
			const scene = new Scene();
			scene.environmentNode = {};

			expect( observer.containsNode( createBuilder( { scene } ) ) ).toBe( false );

		} );

	} );

	describe( 'firstInitialization', () => {

		it( 'returns true only once per render object', () => {

			const observer = createObserver();
			const renderObject = createRenderObject();

			expect( observer.firstInitialization( renderObject ) ).toBe( true );
			expect( observer.renderObjects.has( renderObject ) ).toBe( true );
			expect( observer.firstInitialization( renderObject ) ).toBe( false );

		} );

		it( 'tracks render objects independently', () => {

			const observer = createObserver();
			const renderObjectA = createRenderObject();
			const renderObjectB = createRenderObject();

			expect( observer.firstInitialization( renderObjectA ) ).toBe( true );
			expect( observer.firstInitialization( renderObjectB ) ).toBe( true );
			expect( observer.firstInitialization( renderObjectA ) ).toBe( false );
			expect( observer.firstInitialization( renderObjectB ) ).toBe( false );

		} );

	} );

	describe( 'getRenderObjectData', () => {

		it( 'captures the initial state of object, geometry, material, context and scene', () => {

			const geometry = new BufferGeometry();
			geometry.setAttribute( 'position', new BufferAttribute( new Float32Array( 9 ), 3 ) );

			const material = new MeshBasicMaterial();
			const object = new Mesh( geometry, material );
			object.position.set( 1, 2, 3 );
			object.updateMatrixWorld();

			const renderer = createRenderer();
			const renderObject = createRenderObject( { object, material, geometry, renderer, width: 640, height: 480 } );
			const observer = createObserver();

			const data = observer.getRenderObjectData( renderObject );

			expect( data.geometryId ).toBe( geometry.id );
			expect( data.geometryVersion ).toBe( 0 );
			expect( data.materialVersion ).toBe( 0 );
			expect( data.worldMatrix.equals( object.matrixWorld ) ).toBe( true );
			expect( data.worldMatrix ).not.toBe( object.matrixWorld );
			expect( data.bufferWidth ).toBe( 640 );
			expect( data.bufferHeight ).toBe( 480 );
			expect( data.outputTarget ).toBe( renderer.state.canvasTarget );
			expect( data.environmentIntensity ).toBe( 1 );
			expect( data.environmentRotation.isEuler ).toBe( true );
			expect( data.lights ).toEqual( [] );
			expect( data.center ).toBeUndefined();
			expect( data.version ).toBeUndefined();

		} );

		it( 'returns the cached data for the same render object', () => {

			const observer = createObserver();
			const renderObject = createRenderObject();

			const data = observer.getRenderObjectData( renderObject );

			expect( observer.getRenderObjectData( renderObject ) ).toBe( data );

		} );

		it( 'captures center and morph target influence copies', () => {

			const sprite = new Sprite();
			sprite.geometry = new BufferGeometry();
			const spriteData = createObserver().getRenderObjectData( createRenderObject( { object: sprite, geometry: sprite.geometry, material: sprite.material } ) );

			expect( spriteData.center.equals( sprite.center ) ).toBe( true );
			expect( spriteData.center ).not.toBe( sprite.center );

			const mesh = new Mesh();
			mesh.morphTargetInfluences = [ 0.25, 0.5 ];
			const meshData = createObserver().getRenderObjectData( createRenderObject( { object: mesh } ) );

			expect( meshData.morphTargetInfluences ).toEqual( [ 0.25, 0.5 ] );
			expect( meshData.morphTargetInfluences ).not.toBe( mesh.morphTargetInfluences );

		} );

		it( 'captures instanced mesh versions and the bundle version', () => {

			const geometry = new BufferGeometry();
			const material = new MeshBasicMaterial();
			const instancedMesh = new InstancedMesh( geometry, material, 2 );
			instancedMesh.instanceColor = new InstancedBufferAttribute( new Float32Array( 6 ), 3 );
			instancedMesh.morphTexture = new DataTexture( new Float32Array( 4 ), 1, 1 );

			const bundle = { static: true, version: 7 };
			const data = createObserver().getRenderObjectData( createRenderObject( { object: instancedMesh, geometry, material, bundle } ) );

			expect( data.instanceMatrixVersion ).toBe( 0 );
			expect( data.instanceColorVersion ).toBe( 0 );
			expect( data.morphTextureVersion ).toBe( 0 );
			expect( data.version ).toBe( 7 );

		} );

		it( 'captures batched mesh texture versions', () => {

			const material = new MeshBasicMaterial();
			const batchedMesh = new BatchedMesh( 2, 12, 12, material );

			const data = createObserver().getRenderObjectData( createRenderObject( { object: batchedMesh, geometry: batchedMesh.geometry, material } ) );

			expect( data.matricesTextureVersion ).toBe( 0 );
			expect( data.colorsTextureVersion ).toBeNull();
			expect( data.indirectTextureVersion ).toBe( 0 );

		} );

	} );

	describe( 'getOutputTarget', () => {

		it( 'prefers the active render target', () => {

			const renderTarget = new RenderTarget( 4, 4 );
			const outputRenderTarget = new RenderTarget( 8, 8 );
			const renderer = createRenderer( { renderTarget, outputRenderTarget } );

			expect( createObserver().getOutputTarget( renderer ) ).toBe( renderTarget );

		} );

		it( 'falls back to the output render target', () => {

			const outputRenderTarget = new RenderTarget( 8, 8 );
			const renderer = createRenderer( { outputRenderTarget } );

			expect( createObserver().getOutputTarget( renderer ) ).toBe( outputRenderTarget );

		} );

		it( 'falls back to the canvas target', () => {

			const renderer = createRenderer();

			expect( createObserver().getOutputTarget( renderer ) ).toBe( renderer.state.canvasTarget );

		} );

	} );

	describe( 'hasDynamicInstancing', () => {

		it( 'returns false for non instanced objects', () => {

			expect( createObserver().hasDynamicInstancing( new Mesh() ) ).toBe( false );

		} );

		it( 'returns false for statically drawn instanced meshes', () => {

			const instancedMesh = new InstancedMesh( new BufferGeometry(), new MeshBasicMaterial(), 2 );

			expect( createObserver().hasDynamicInstancing( instancedMesh ) ).toBe( false );

		} );

		it( 'returns true if the instance matrix uses dynamic draw usage', () => {

			const instancedMesh = new InstancedMesh( new BufferGeometry(), new MeshBasicMaterial(), 2 );
			instancedMesh.instanceMatrix.setUsage( DynamicDrawUsage );

			expect( createObserver().hasDynamicInstancing( instancedMesh ) ).toBe( true );

		} );

		it( 'returns true if the instance color uses dynamic draw usage', () => {

			const instancedMesh = new InstancedMesh( new BufferGeometry(), new MeshBasicMaterial(), 2 );
			instancedMesh.instanceColor = new InstancedBufferAttribute( new Float32Array( 6 ), 3 );
			instancedMesh.instanceColor.setUsage( DynamicDrawUsage );

			expect( createObserver().hasDynamicInstancing( instancedMesh ) ).toBe( true );

		} );

	} );

	describe( 'needsVelocity', () => {

		it( 'returns false without an MRT', () => {

			expect( createObserver().needsVelocity( createRenderer() ) ).toBe( false );

		} );

		it( 'returns false if the MRT has no velocity channel', () => {

			expect( createObserver().needsVelocity( createRenderer( { mrt: new Map() } ) ) ).toBe( false );

		} );

		it( 'returns true if the MRT has a velocity channel', () => {

			const mrt = new Map( [ [ 'velocity', { isTexture: true } ] ] );

			expect( createObserver().needsVelocity( createRenderer( { mrt } ) ) ).toBe( true );

		} );

	} );

	describe( 'getAttributesData', () => {

		it( 'maps attribute names to id and version', () => {

			const geometry = new BufferGeometry();
			geometry.setAttribute( 'position', new BufferAttribute( new Float32Array( 9 ), 3 ) );

			const data = createObserver().getAttributesData( geometry.attributes );

			expect( data ).toEqual( { position: { id: geometry.attributes.position.id, version: 0 } } );

		} );

		it( 'uses the interleaved buffer identity and version for interleaved attributes', () => {

			const interleavedBuffer = new InterleavedBuffer( new Float32Array( 12 ), 3 );
			const attribute = new InterleavedBufferAttribute( interleavedBuffer, 3, 0 );
			const geometry = new BufferGeometry();
			geometry.setAttribute( 'uv', attribute );

			const data = createObserver().getAttributesData( geometry.attributes );

			expect( data.uv.id ).toBe( interleavedBuffer.uuid );
			expect( data.uv.id ).not.toBe( attribute.id );
			expect( data.uv.version ).toBe( 0 );

			interleavedBuffer.needsUpdate = true;

			expect( createObserver().getAttributesData( geometry.attributes ).uv.version ).toBe( 1 );

		} );

		it( 'returns an empty object for empty attributes', () => {

			expect( createObserver().getAttributesData( {} ) ).toEqual( {} );

		} );

	} );

	describe( 'getGeometryData', () => {

		it( 'captures geometry state and caches it per geometry', () => {

			const geometry = new BufferGeometry();
			geometry.setAttribute( 'position', new BufferAttribute( new Float32Array( 9 ), 3 ) );
			geometry.setIndex( [ 0, 1, 2 ] );
			geometry.setDrawRange( 1, 2 );

			const observer = createObserver();
			const data = observer.getGeometryData( geometry );

			expect( data._renderId ).toBe( - 1 );
			expect( data._version ).toBe( 0 );
			expect( data.attributes.position ).toEqual( { id: geometry.attributes.position.id, version: 0 } );
			expect( data.indexId ).toBe( geometry.index.id );
			expect( data.indexVersion ).toBe( 0 );
			expect( data.drawRange ).toEqual( { start: 1, count: 2 } );
			expect( observer.getGeometryData( geometry ) ).toBe( data );

			const otherGeometry = new BufferGeometry();

			expect( observer.getGeometryData( otherGeometry ) ).not.toBe( data );

		} );

		it( 'invalidates the geometry data on dispose', () => {

			const geometry = new BufferGeometry();
			const observer = createObserver();
			const data = observer.getGeometryData( geometry );

			expect( data._version ).toBe( 0 );

			geometry.dispose();
			expect( data._version ).toBe( 1 );

			geometry.dispose();
			expect( data._version ).toBe( 2 );

		} );

	} );

	describe( 'getTextureData', () => {

		it( 'invalidates the texture data on texture dispose', () => {

			const texture = new Texture();
			const observer = createObserver();
			const data = observer.getTextureData( texture );

			expect( data._version ).toBe( 0 );
			expect( observer.getTextureData( texture ) ).toBe( data );

			texture.dispose();
			expect( data._version ).toBe( 1 );

		} );

		it( 'listens to the render target dispose event for render target textures', () => {

			const renderTarget = new RenderTarget( 2, 2 );
			const texture = renderTarget.texture;
			const data = createObserver().getTextureData( texture );

			texture.dispose();
			expect( data._version ).toBe( 0 );

			renderTarget.dispose();
			expect( data._version ).toBe( 1 );

		} );

	} );

	describe( 'getMaterialData', () => {

		it( 'creates a snapshot of the tracked material uniforms', () => {

			const material = new MeshBasicMaterial();
			material.color.setHex( 0xff0000 );
			material.opacity = 0.5;

			const data = createObserver().getMaterialData( material );

			expect( data._renderId ).toBe( - 1 );
			expect( data._version ).toBe( 0 );
			expect( data.opacity ).toBe( 0.5 );
			expect( data.wireframe ).toBe( false );
			expect( data.color.isColor ).toBe( true );
			expect( data.color.equals( material.color ) ).toBe( true );
			expect( data.color ).not.toBe( material.color );
			expect( data.map ).toBeNull();
			expect( 'anisotropy' in data ).toBe( false );

		} );

		it( 'stores texture references by id and version', () => {

			const material = new MeshBasicMaterial();
			material.map = new Texture();

			const data = createObserver().getMaterialData( material );

			expect( data.map ).toEqual( { id: material.map.id, version: 0, cacheVersion: 0 } );

		} );

		it( 'caches the snapshot per material and isolates it from later mutations', () => {

			const material = new MeshBasicMaterial();
			const observer = createObserver();
			const data = observer.getMaterialData( material );

			expect( observer.getMaterialData( material ) ).toBe( data );

			material.color.setHex( 0x00ff00 );

			expect( data.color.getHex() ).toBe( 0xffffff );

		} );

	} );

	describe( 'equals', () => {

		it( 'returns true for an unchanged render object', () => {

			const observer = createObserver();
			const renderObject = createRenderObject();

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );
			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

		} );

		it( 'detects world matrix changes and syncs the cached matrix', () => {

			const observer = createObserver();
			const renderObject = createRenderObject();
			const { object } = renderObject;

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			object.position.set( 1, 0, 0 );
			object.updateMatrixWorld();

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.renderObjects.get( renderObject ).worldMatrix.equals( object.matrixWorld ) ).toBe( true );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects changed scalar material properties', () => {

			const observer = createObserver();
			const material = new MeshBasicMaterial();
			material.opacity = 1;
			const renderObject = createRenderObject( { material } );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			material.opacity = 0.25;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects changed color material properties', () => {

			const observer = createObserver();
			const material = new MeshBasicMaterial();
			const renderObject = createRenderObject( { material } );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			material.color.setHex( 0x123456 );

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects material properties that are assigned after monitoring started', () => {

			const observer = createObserver();
			const material = new MeshBasicMaterial();
			const renderObject = createRenderObject( { material } );

			expect( material.map ).toBeNull();
			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			material.map = new Texture();
			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

			material.map = null;
			expect( observer.equals( renderObject, [], 4 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 5 ) ).toBe( true );

		} );

		it( 'detects texture version, texture identity and texture disposal changes', () => {

			const observer = createObserver();
			const material = new MeshBasicMaterial();
			const map = new Texture();
			material.map = map;
			const renderObject = createRenderObject( { material } );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			map.needsUpdate = true;
			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

			map.dispose();
			expect( observer.equals( renderObject, [], 4 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 5 ) ).toBe( true );

			material.map = new Texture();
			expect( observer.equals( renderObject, [], 6 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 7 ) ).toBe( true );

		} );

		it( 'does not track material properties outside of the refresh uniforms', () => {

			const observer = createObserver();
			const material = new MeshBasicMaterial();
			const renderObject = createRenderObject( { material } );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			material.customValue = 42;
			material.userData.changed = true;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( true );

		} );

		it( 'checks the material only once per render id', () => {

			const observer = createObserver();
			const material = new MeshBasicMaterial();
			const renderObjectA = createRenderObject( { material } );
			const renderObjectB = createRenderObject( { material } );

			expect( observer.equals( renderObjectA, [], 1 ) ).toBe( true );
			expect( observer.equals( renderObjectB, [], 1 ) ).toBe( true );

			material.opacity = 0.5;

			// the material snapshot was already checked in this render id
			expect( observer.equals( renderObjectA, [], 1 ) ).toBe( true );

			// the new render id performs the check once, the shared version invalidates both objects
			expect( observer.equals( renderObjectA, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObjectB, [], 2 ) ).toBe( true );

		} );

		it( 'detects changed buffer dimensions', () => {

			const observer = createObserver();
			const renderObject = createRenderObject( { width: 800, height: 600 } );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.context.width = 1024;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.renderObjects.get( renderObject ).bufferWidth ).toBe( 1024 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

			renderObject.context.height = 512;

			expect( observer.equals( renderObject, [], 4 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 5 ) ).toBe( true );

		} );

		it( 'detects a replaced geometry', () => {

			const observer = createObserver();
			const geometry = new BufferGeometry();
			const renderObject = createRenderObject( { geometry } );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			const otherGeometry = new BufferGeometry();
			renderObject.geometry = otherGeometry;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.renderObjects.get( renderObject ).geometryId ).toBe( otherGeometry.id );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects geometry attribute updates', () => {

			const observer = createObserver();
			const geometry = new BufferGeometry();
			const position = new BufferAttribute( new Float32Array( 9 ), 3 );
			geometry.setAttribute( 'position', position );
			const renderObject = createRenderObject( { geometry } );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			position.needsUpdate = true;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects added and removed geometry attributes', () => {

			const observer = createObserver();
			const geometry = new BufferGeometry();
			geometry.setAttribute( 'position', new BufferAttribute( new Float32Array( 9 ), 3 ) );
			const renderObject = createRenderObject( { geometry } );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			geometry.setAttribute( 'normal', new BufferAttribute( new Float32Array( 9 ), 3 ) );

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

			geometry.deleteAttribute( 'normal' );

			expect( observer.equals( renderObject, [], 4 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 5 ) ).toBe( true );

		} );

		it( 'detects interleaved attribute updates', () => {

			const observer = createObserver();
			const geometry = new BufferGeometry();
			const interleavedBuffer = new InterleavedBuffer( new Float32Array( 12 ), 3 );
			geometry.setAttribute( 'uv', new InterleavedBufferAttribute( interleavedBuffer, 3, 0 ) );
			const renderObject = createRenderObject( { geometry } );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			interleavedBuffer.needsUpdate = true;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects index and draw range changes', () => {

			const observer = createObserver();
			const geometry = new BufferGeometry();
