	describe( 'getLightsData', () => {

		it( 'ignores lights without maps or shadows', () => {

			const observer = createPlainObserver();

			expect( observer.getLightsData( [], [] ) ).toEqual( [] );
			expect( observer.getLightsData( [ new AmbientLight() ], [] ) ).toEqual( [] );
			expect( observer.getLightsData( [ new SpotLight() ], [] ) ).toEqual( [] );

		} );

		it( 'records the shadow map size of shadow casting lights', () => {

			const observer = createPlainObserver();
			const light = new DirectionalLight();
			light.castShadow = true;
			light.shadow.mapSize.set( 1024, 2048 );

			expect( observer.getLightsData( [ light ], [] ) ).toEqual( [
				{ shadowMapWidth: 1024, shadowMapHeight: 2048 }
			] );

		} );

		it( 'records spot light maps together with their texture cache version', () => {

			const observer = createPlainObserver();
			const light = new SpotLight();
			light.map = new Texture();

			expect( observer.getLightsData( [ light ], [] ) ).toEqual( [
				{ map: 0, cacheVersion: 0 }
			] );

			light.castShadow = true;

			expect( observer.getLightsData( [ light ], [] ) ).toEqual( [
				{ map: 0, cacheVersion: 0, shadowMapWidth: 512, shadowMapHeight: 512 }
			] );

			light.map.needsUpdate = true;

			expect( observer.getLightsData( [ light ], [] )[ 0 ].map ).toBe( 1 );

		} );

		it( 'reuses the given target array', () => {

			const observer = createPlainObserver();
			const light = new DirectionalLight();
			light.castShadow = true;

			const target = [ { stale: true } ];
			const result = observer.getLightsData( [ light ], target );

			expect( result ).toBe( target );
			expect( result ).toEqual( [ { shadowMapWidth: 512, shadowMapHeight: 512 } ] );

		} );

	} );

	describe( 'getLights', () => {

		it( 'caches the collected lights per lights node and render id', () => {

			const observer = createPlainObserver();
			const light = new DirectionalLight();
			light.castShadow = true;
			const lightsNode = createLightsNode( [ light ] );

			const first = observer.getLights( lightsNode, 1 );

			expect( first ).toEqual( [ { shadowMapWidth: 512, shadowMapHeight: 512 } ] );
			expect( observer.getLights( lightsNode, 1 ) ).toBe( first );

			light.shadow.mapSize.set( 1024, 1024 );

			const second = observer.getLights( lightsNode, 2 );

			expect( second ).toBe( first );
			expect( second ).toEqual( [ { shadowMapWidth: 1024, shadowMapHeight: 1024 } ] );

		} );

		it( 'collects the builtin lights of the node', () => {

			const observer = createPlainObserver();
