class FakeBackend extends Backend {

	constructor( { canvas = createCanvas(), initError = null } = {} ) {

		super( { canvas } );

		this.coordinateSystem = 42;
		this.initError = initError;
		this.capabilities = {
			getMaxAnisotropy: jest.fn( () => 16 )
		};

		this.init = jest.fn( async ( renderer ) => {

			if ( this.initError !== null ) throw this.initError;
			this.renderer = renderer;

		} );
		this.dispose = jest.fn( async () => {} );
		this.clear = jest.fn();
		this.getContext = jest.fn( () => ( { context: 'fake' } ) );
		this.hasFeature = jest.fn( ( name ) => name === 'supported-feature' );
		this.resetState = jest.fn();
		this.setScissorTest = jest.fn();
		this.updateSize = jest.fn();
		this.destroyCanvasTarget = jest.fn();
		this.resolveTimestampsAsync = jest.fn( async ( type ) => ( { type } ) );
		this.getArrayBufferAsync = jest.fn( async () => ( { byteLength: 4 } ) );
		this.copyTextureToBuffer = jest.fn( async () => new Uint8Array( [ 1, 2, 3, 4 ] ) );
		this.copyTextureToTexture = jest.fn();
		this.copyFramebufferToTexture = jest.fn();
		this.initRenderTarget = jest.fn();
		this.beginRender = jest.fn();
		this.finishRender = jest.fn();

	}

}

describe( 'Renderer', () => {

	let originalSelf;
	let hadSelf;
	let renderer;

	beforeEach( () => {

		hadSelf = Object.prototype.hasOwnProperty.call( globalThis, 'self' );
		originalSelf = globalThis.self;

		let nextFrameId = 1;
		const callbacks = new Map();

		globalThis.self = {
			requestAnimationFrame: jest.fn( ( callback ) => {

				const id = nextFrameId ++;
				callbacks.set( id, callback );
				return id;

			} ),
			cancelAnimationFrame: jest.fn( ( id ) => {

				callbacks.delete( id );

			} ),
			__runAnimationFrame( time = 0 ) {

				const pending = Array.from( callbacks.entries() );
				callbacks.clear();

				for ( const [ , callback ] of pending ) callback( time );

			}
		};

		renderer = null;

	} );

	afterEach( async () => {

		if ( renderer !== null ) {

			await renderer.dispose();

		}

		if ( hadSelf ) {

			globalThis.self = originalSelf;

		} else {

			delete globalThis.self;

		}

	} );

	describe( 'construction and configuration', () => {

		test( 'exposes the expected defaults and backend', () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );

			expect( renderer.isRenderer ).toBe( true );
			expect( renderer.backend ).toBe( backend );
			expect( renderer.domElement ).toBe( backend.getDomElement() );
			expect( renderer.coordinateSystem ).toBe( 42 );

			expect( renderer.autoClear ).toBe( true );
			expect( renderer.autoClearColor ).toBe( true );
			expect( renderer.autoClearDepth ).toBe( true );
			expect( renderer.autoClearStencil ).toBe( true );
			expect( renderer.alpha ).toBe( true );
			expect( renderer.depth ).toBe( true );
			expect( renderer.stencil ).toBe( false );
			expect( renderer.logarithmicDepthBuffer ).toBe( false );
			expect( renderer.reversedDepthBuffer ).toBe( false );
			expect( renderer.outputColorSpace ).toBe( SRGBColorSpace );
			expect( renderer.toneMapping ).toBe( NoToneMapping );
			expect( renderer.toneMappingExposure ).toBe( 1 );
			expect( renderer.sortObjects ).toBe( true );
			expect( renderer.transparent ).toBe( true );
			expect( renderer.opaque ).toBe( true );
			expect( renderer.shadowMap ).toEqual( { enabled: false, transmitted: false, type: PCFShadowMap } );
			expect( renderer.xr ).toBeDefined();
			expect( renderer.xr.enabled ).toBe( false );

		} );

		test( 'honors constructor options and MSAA sample configuration', () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend, {
				logarithmicDepthBuffer: true,
				reversedDepthBuffer: true,
				alpha: false,
				depth: false,
				stencil: true,
				antialias: true,
				multiview: true,
				outputBufferType: LinearSRGBColorSpace
			} );

			expect( renderer.logarithmicDepthBuffer ).toBe( true );
			expect( renderer.reversedDepthBuffer ).toBe( true );
			expect( renderer.alpha ).toBe( false );
			expect( renderer.depth ).toBe( false );
			expect( renderer.stencil ).toBe( true );
			expect( renderer.samples ).toBe( 4 );
			expect( renderer.xr.multiview ).toBe( true );
			expect( renderer.getOutputBufferType() ).toBe( LinearSRGBColorSpace );
			expect( renderer.getClearAlpha() ).toBe( 1 );

		} );

		test( 'uses an explicit sample count over the antialias default', () => {

			renderer = new Renderer( new FakeBackend(), { antialias: true, samples: 8 } );
			expect( renderer.samples ).toBe( 8 );

			renderer = null;

			renderer = new Renderer( new FakeBackend(), { samples: 0 } );
			expect( renderer.samples ).toBe( 0 );

		} );

		test( 'tracks the default output values when a custom render target is active', () => {

			renderer = new Renderer( new FakeBackend() );

			renderer.toneMapping = 3;
			renderer.outputColorSpace = SRGBColorSpace;
			renderer.setRenderTarget( { samples: 6 } );

			expect( renderer.currentToneMapping ).toBe( NoToneMapping );
			expect( renderer.currentColorSpace ).toBe( ColorManagement.workingColorSpace );
			expect( renderer.currentSamples ).toBe( 6 );
			expect( renderer.isOutputTarget ).toBe( false );

		} );

		test( 'switches highPrecision through the public accessor', () => {

			renderer = new Renderer( new FakeBackend() );

			expect( renderer.highPrecision ).toBe( false );

			renderer.highPrecision = true;
			expect( renderer.highPrecision ).toBe( true );

			renderer.highPrecision = false;
			expect( renderer.highPrecision ).toBe( false );

		} );

		test( 'sets and returns MRT and render object callback state', () => {

			renderer = new Renderer( new FakeBackend() );
			const mrt = { id: 'mrt' };
			const callback = jest.fn();

			expect( renderer.setMRT( mrt ) ).toBe( renderer );
			expect( renderer.getMRT() ).toBe( mrt );

			renderer.setRenderObjectFunction( callback );
			expect( renderer.getRenderObjectFunction() ).toBe( callback );

			renderer.setRenderObjectFunction( null );
			expect( renderer.getRenderObjectFunction() ).toBe( null );

		} );

		test( 'replaces the inspector and attaches it to the renderer', () => {

			renderer = new Renderer( new FakeBackend() );
			const oldInspector = renderer.inspector;
			const nextInspector = new InspectorBase();

			renderer.inspector = nextInspector;

			expect( renderer.inspector ).toBe( nextInspector );
			expect( nextInspector.getRenderer() ).toBe( renderer );
			expect( oldInspector.getRenderer() ).toBe( null );

		} );

		test( 'exposes the compileAsync method through the compile alias', () => {

			renderer = new Renderer( new FakeBackend() );
			expect( renderer.compile ).toBe( renderer.compileAsync );

		} );

	} );

	describe( 'initialization', () => {

		test( 'initializes the backend once and reports its initialized state', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );

			expect( renderer.hasInitialized() ).toBe( false );

			const [ first, second ] = await Promise.all( [ renderer.init(), renderer.init() ] );

			expect( first ).toBe( renderer );
			expect( second ).toBe( renderer );
			expect( renderer.hasInitialized() ).toBe( true );
			expect( backend.init ).toHaveBeenCalledTimes( 1 );
			expect( backend.init ).toHaveBeenCalledWith( renderer );
			expect( renderer.currentSamples ).toBe( 0 );

		} );

		test( 'uses a fallback backend when the primary backend cannot initialize', async () => {

			const primary = new FakeBackend( { initError: new Error( 'primary failed' ) } );
			const fallback = new FakeBackend();
			const getFallback = jest.fn( ( error ) => {

				expect( error.message ).toBe( 'primary failed' );
				return fallback;

			} );

			renderer = new Renderer( primary, { getFallback } );
			await renderer.init();

			expect( getFallback ).toHaveBeenCalledTimes( 1 );
			expect( renderer.backend ).toBe( fallback );
			expect( fallback.init ).toHaveBeenCalledWith( renderer );
			expect( renderer.hasInitialized() ).toBe( true );
			expect( renderer.coordinateSystem ).toBe( 42 );

		} );

		test( 'rejects initialization when primary and fallback fail', async () => {

			const primaryError = new Error( 'primary failed' );
			const fallbackError = new Error( 'fallback failed' );
			const primary = new FakeBackend( { initError: primaryError } );
			const fallback = new FakeBackend( { initError: fallbackError } );

			renderer = new Renderer( primary, { getFallback: () => fallback } );

			await expect( renderer.init() ).rejects.toBe( fallbackError );
			expect( renderer.hasInitialized() ).toBe( false );

		} );

		test( 'rejects initialization when no fallback is available', async () => {

			const error = new Error( 'backend failed' );
			renderer = new Renderer( new FakeBackend( { initError: error } ) );

			await expect( renderer.init() ).rejects.toBe( error );
			expect( renderer.hasInitialized() ).toBe( false );

		} );

		test( 'stores and reports the configured animation loop', async () => {

			renderer = new Renderer( new FakeBackend() );
			const callback = jest.fn();

			await renderer.setAnimationLoop( callback );

			expect( renderer.hasInitialized() ).toBe( true );
			expect( renderer.getAnimationLoop() ).toBe( callback );

			globalThis.self.__runAnimationFrame( 25 );
			expect( callback ).toHaveBeenCalledWith( 25, undefined );

		} );

	} );

	describe( 'backend delegation', () => {

		test( 'delegates context, anisotropy, features, and timestamp resolution', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend, { trackTimestamp: true } );

			expect( renderer.getContext() ).toBe( backend.getContext() );
			expect( renderer.getMaxAnisotropy() ).toBe( 16 );

			await expect( renderer.resolveTimestampsAsync( 'compute' ) ).resolves.toEqual( { type: 'compute' } );
			expect( backend.resolveTimestampsAsync ).toHaveBeenCalledWith( 'compute' );

			expect( renderer.hasFeature( 'supported-feature' ) ).toBe( true );

		} );

		test( 'guards the synchronous feature query before initialization', () => {

			renderer = new Renderer( new FakeBackend() );
			expect( () => renderer.hasFeature( 'anything' ) ).toThrow( 'before the backend is initialized' );

		} );

		test( 'delegates resetState only after initialization', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );

			expect( () => renderer.resetState() ).toThrow( 'before the backend is initialized' );

			await renderer.init();
			renderer.resetState();

			expect( backend.resetState ).toHaveBeenCalledTimes( 1 );

		} );

		test( 'delegates array-buffer reads and validates offset/count alignment', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			const attribute = { isBufferAttribute: true };

			await expect( renderer.getArrayBufferAsync( attribute, null, 8, 12 ) ).resolves.toEqual( { byteLength: 4 } );
			expect( backend.getArrayBufferAsync ).toHaveBeenCalledWith( attribute, null, 8, 12 );

			await expect( renderer.getArrayBufferAsync( attribute, null, 2, - 1 ) ).rejects.toThrow( 'multiple of 4' );
			await expect( renderer.getArrayBufferAsync( attribute, null, 0, 6 ) ).rejects.toThrow( 'multiple of 4' );

		} );

		test( 'delegates render-target pixel reads using the selected texture and face', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			const texture = { id: 'texture' };
			const renderTarget = { textures: [ { id: 'zero' }, texture ] };

			const result = await renderer.readRenderTargetPixelsAsync( renderTarget, 1, 2, 3, 4, 1, 5 );

			expect( result ).toEqual( new Uint8Array( [ 1, 2, 3, 4 ] ) );
			expect( backend.copyTextureToBuffer ).toHaveBeenCalledWith( texture, 1, 2, 3, 4, 5 );

		} );

	} );

	describe( 'canvas target and sizing', () => {

		test( 'reports and updates logical size, drawing-buffer size, and pixel ratio', () => {

			const backend = new FakeBackend( { canvas: createCanvas( 320, 180 ) } );
			renderer = new Renderer( backend );
			const size = new Vector2();
			const drawingBufferSize = new Vector2();

			expect( renderer.getSize( size ) ).toBe( size );
			expect( size.toArray() ).toEqual( [ 320, 180 ] );
			expect( renderer.getPixelRatio() ).toBe( 1 );

			renderer.setPixelRatio( 2 );
			expect( renderer.getPixelRatio() ).toBe( 2 );
			expect( renderer.domElement.width ).toBe( 640 );
			expect( renderer.domElement.height ).toBe( 360 );
			expect( renderer.getDrawingBufferSize( drawingBufferSize ).toArray() ).toEqual( [ 640, 360 ] );

			renderer.setSize( 400, 200, false );
			expect( renderer.getSize( size ).toArray() ).toEqual( [ 400, 200 ] );
			expect( renderer.domElement.style.width ).toBeUndefined();

			renderer.setDrawingBufferSize( 200, 100, 3 );
			expect( renderer.domElement.width ).toBe( 600 );
			expect( renderer.domElement.height ).toBe( 300 );
			expect( renderer.getPixelRatio() ).toBe( 3 );

		} );

		test( 'notifies the backend of canvas resize after initialization', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			await renderer.init();

			renderer.setSize( 123, 456 );

			expect( backend.updateSize ).toHaveBeenCalledTimes( 1 );

		} );

		test( 'stores viewport and scissor state and forwards scissor-test changes', () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			const viewport = new Vector4();
			const scissor = new Vector4();

			renderer.setViewport( 1, 2, 30, 40, 0.25, 0.75 );
			expect( renderer.getViewport( viewport ) ).toBe( viewport );
			expect( viewport ).toEqual( new Vector4( 1, 2, 30, 40 ) );
			expect( viewport.minDepth ).toBe( 0.25 );
			expect( viewport.maxDepth ).toBe( 0.75 );

			renderer.setScissor( new Vector4( 4, 5, 6, 7 ) );
			expect( renderer.getScissor( scissor ) ).toBe( scissor );
			expect( scissor ).toEqual( new Vector4( 4, 5, 6, 7 ) );

			expect( renderer.getScissorTest() ).toBe( false );
			renderer.setScissorTest( true );
			expect( renderer.getScissorTest() ).toBe( true );
			expect( backend.setScissorTest ).toHaveBeenCalledWith( true );

		} );

		test( 'replaces the canvas target and reconnects resize notifications', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			await renderer.init();

			const oldTarget = renderer.getCanvasTarget();
			const newTarget = new CanvasTarget( createCanvas( 50, 60 ) );

			renderer.setCanvasTarget( newTarget );

			expect( renderer.getCanvasTarget() ).toBe( newTarget );
			expect( renderer.domElement ).toBe( newTarget.domElement );

			backend.updateSize.mockClear();
			oldTarget.setSize( 10, 10 );
			expect( backend.updateSize ).not.toHaveBeenCalled();

			newTarget.setSize( 20, 20 );
			expect( backend.updateSize ).toHaveBeenCalledTimes( 1 );

		} );

		test( 'does not resize while XR is presenting', () => {

			renderer = new Renderer( new FakeBackend() );
			renderer.xr.isPresenting = true;

			renderer.setSize( 999, 888 );
			renderer.setDrawingBufferSize( 777, 666, 2 );

			expect( renderer.getSize( new Vector2() ).toArray() ).toEqual( [ 300, 150 ] );
			expect( renderer.getPixelRatio() ).toBe( 1 );

		} );

	} );

	describe( 'render targets and clear state', () => {

		test( 'sets and clears render target, output target, cube face, and mip level state', () => {

			renderer = new Renderer( new FakeBackend() );
			const renderTarget = { id: 'render-target' };
			const outputTarget = { id: 'output-target' };

			expect( renderer.getRenderTarget() ).toBe( null );
			expect( renderer.getActiveCubeFace() ).toBe( 0 );
			expect( renderer.getActiveMipmapLevel() ).toBe( 0 );
			expect( renderer.isOutputTarget ).toBe( true );

			renderer.setRenderTarget( renderTarget, 2, 3 );
			expect( renderer.getRenderTarget() ).toBe( renderTarget );
			expect( renderer.getActiveCubeFace() ).toBe( 2 );
			expect( renderer.getActiveMipmapLevel() ).toBe( 3 );

			renderer.setOutputRenderTarget( renderTarget );
			expect( renderer.getOutputRenderTarget() ).toBe( renderTarget );
			expect( renderer.isOutputTarget ).toBe( true );

			renderer.setOutputRenderTarget( outputTarget );
			expect( renderer.isOutputTarget ).toBe( false );

			renderer.setRenderTarget( null );
			renderer.setOutputRenderTarget( null );
			expect( renderer.isOutputTarget ).toBe( true );

		} );

		test( 'stores clear color, alpha, depth, and stencil values', () => {

			renderer = new Renderer( new FakeBackend() );
			const color = new Color();

			renderer.setClearColor( new Color( 0.1, 0.2, 0.3 ), 0.4 );
			expect( renderer.getClearColor( color ) ).toBe( color );
			expect( color.r ).toBeCloseTo( 0.1 );
			expect( color.g ).toBeCloseTo( 0.2 );
			expect( color.b ).toBeCloseTo( 0.3 );
			expect( renderer.getClearAlpha() ).toBe( 0.4 );

			renderer.setClearAlpha( 0.75 );
			expect( renderer.getClearAlpha() ).toBe( 0.75 );

			renderer.setClearDepth( 0.25 );
			expect( renderer.getClearDepth() ).toBe( 0.25 );

			renderer.setClearStencil( 7 );
			expect( renderer.getClearStencil() ).toBe( 7 );

		} );

		test( 'inverts clear depth when reversed depth is enabled', () => {

			renderer = new Renderer( new FakeBackend(), { reversedDepthBuffer: true } );
			renderer.setClearDepth( 0.25 );

			expect( renderer.getClearDepth() ).toBe( 0.75 );

		} );

		test( 'determines whether an output framebuffer target is necessary', () => {

			renderer = new Renderer( new FakeBackend() );

			expect( renderer.needsFrameBufferTarget ).toBe( true );
			expect( renderer.currentSamples ).toBe( 0 );

			renderer.outputColorSpace = LinearSRGBColorSpace;
			expect( renderer.needsFrameBufferTarget ).toBe( false );
			expect( renderer.currentSamples ).toBe( 0 );

			renderer.toneMapping = 2;
			expect( renderer.needsFrameBufferTarget ).toBe( true );

			renderer.toneMapping = NoToneMapping;
			renderer.outputColorSpace = SRGBColorSpace;
			expect( renderer.needsFrameBufferTarget ).toBe( true );

		} );

		test( 'guards manual clear calls before initialization', () => {

			renderer = new Renderer( new FakeBackend() );

			expect( () => renderer.clear() ).toThrow( '.clear() called before the backend is initialized' );
			expect( () => renderer.clearColor() ).toThrow( '.clear() called before the backend is initialized' );

		} );

		test( 'forwards clear operations and their channel selection to the backend', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			await renderer.init();
			renderer.outputColorSpace = LinearSRGBColorSpace;

			renderer.clear();
			expect( backend.clear ).toHaveBeenLastCalledWith( true, true, true, null );

			renderer.clearColor();
			expect( backend.clear ).toHaveBeenLastCalledWith( true, false, false, null );

			renderer.clearDepth();
			expect( backend.clear ).toHaveBeenLastCalledWith( false, true, false, null );

			renderer.clearStencil();
			expect( backend.clear ).toHaveBeenLastCalledWith( false, false, true, null );

		} );

		test( 'returns null from isOccluded when no render context is active', () => {

			renderer = new Renderer( new FakeBackend() );
			expect( renderer.isOccluded( { id: 'object' } ) ).toBe( null );

		} );

	} );

	describe( 'rendering and compute guards', () => {

		test( 'throws from render before initialization', () => {

			renderer = new Renderer( new FakeBackend() );
			const scene = new Scene();
			const camera = new PerspectiveCamera();

			expect( () => renderer.render( scene, camera ) ).toThrow( '.render() called before the backend is initialized' );

		} );

		test( 'renders an empty scene after initialization', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			await renderer.init();
			renderer.outputColorSpace = LinearSRGBColorSpace;

			const scene = new Scene();
			const camera = new PerspectiveCamera();

			renderer.render( scene, camera );

			expect( backend.beginRender ).toHaveBeenCalledTimes( 1 );
			expect( backend.finishRender ).toHaveBeenCalledTimes( 1 );
			expect( renderer.info.render.calls ).toBe( 1 );

		} );

		test( 'does not render after the device is reported lost', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			await renderer.init();
			renderer.outputColorSpace = LinearSRGBColorSpace;
			const consoleError = jest.spyOn( console, 'error' ).mockImplementation( () => {} );

			renderer.onDeviceLost( { api: 'WebGPU', message: 'gone', reason: 'test' } );
			renderer.render( new Scene(), new PerspectiveCamera() );

			expect( consoleError ).toHaveBeenCalled();
			expect( backend.beginRender ).not.toHaveBeenCalled();
			consoleError.mockRestore();

		} );

		test( 'validates compute node inputs', async () => {

			renderer = new Renderer( new FakeBackend() );
			await renderer.init();

			expect( () => renderer.compute( [] ) ).toThrow( 'expects a "ComputeNode"' );
			expect( () => renderer.compute( { isComputeNode: false } ) ).toThrow( 'expects a "ComputeNode"' );

			const definedComputeNode = {
				isComputeNode: true,
				count: 1,
				dispatchSize: null
			};
			expect( () => renderer.compute( definedComputeNode, 8 ) ).toThrow( 'A dispatch size cannot be passed' );

		} );

		test( 'validates compileComputeAsync input after initialization', async () => {

			renderer = new Renderer( new FakeBackend() );
			await renderer.init();

			await expect( renderer.compileComputeAsync( [] ) ).rejects.toThrow( 'expects a "ComputeNode"' );
			await expect( renderer.compileComputeAsync( null ) ).rejects.toThrow( 'expects a "ComputeNode"' );

		} );

		test( 'returns early from compile operations after device loss', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			renderer.onDeviceLost( { api: 'WebGPU', message: 'gone' } );

			await expect( renderer.compileAsync( new Scene(), new PerspectiveCamera() ) ).resolves.toBeUndefined();
			await expect( renderer.compileComputeAsync( [] ) ).resolves.toBeUndefined();
			expect( backend.init ).not.toHaveBeenCalled();

		} );

	} );

	describe( 'texture and resource helpers', () => {

		test( 'guards texture and render-target initialization before init', () => {

			renderer = new Renderer( new FakeBackend() );

			expect( () => renderer.initTexture( {} ) ).toThrow( '.initTexture() called before the backend is initialized' );
			expect( () => renderer.initRenderTarget( {} ) ).toThrow( '.initRenderTarget() called before the backend is initialized' );

		} );

		test( 'rejects invalid framebuffer copy rectangles without touching the backend', () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			const consoleError = jest.spyOn( console, 'error' ).mockImplementation( () => {} );
			const texture = { image: { width: 4, height: 4 } };

			renderer.copyFramebufferToTexture( texture, { x: 0, y: 0 } );

			expect( consoleError ).toHaveBeenCalled();
			expect( backend.copyFramebufferToTexture ).not.toHaveBeenCalled();
			consoleError.mockRestore();

		} );

		test( 'waits for GPU as a harmless deprecated no-op', async () => {

			renderer = new Renderer( new FakeBackend() );
			const consoleError = jest.spyOn( console, 'error' ).mockImplementation( () => {} );

			await expect( renderer.waitForGPU() ).resolves.toBeUndefined();
			expect( consoleError ).toHaveBeenCalled();
			consoleError.mockRestore();

		} );

	} );

	describe( 'disposal', () => {

		test( 'disposes backend resources and resets the active render target', async () => {

			const backend = new FakeBackend();
			renderer = new Renderer( backend );
			await renderer.init();

			const target = { id: 'target' };
			renderer.setRenderTarget( target );

			await renderer.dispose();

