			manager.setReferenceSpaceType( 'local' );
			expect( manager.getReferenceSpaceType() ).toBe( 'local' );
			expect( warn ).toHaveBeenCalledWith( 'THREE.XRManager: Cannot change reference space type while presenting.' );

			warn.mockRestore();

		} );

		it( 'prefers a custom reference space and falls back to the session reference space', () => {

			const manager = new XRManager( createRenderer() );
			const sessionSpace = { name: 'session' };
			const customSpace = { name: 'custom' };

			manager._referenceSpace = sessionSpace;
			expect( manager.getReferenceSpace() ).toBe( sessionSpace );

			manager.setReferenceSpace( customSpace );
			expect( manager.getReferenceSpace() ).toBe( customSpace );

			manager.setReferenceSpace( null );
			expect( manager.getReferenceSpace() ).toBe( sessionSpace );

		} );

		it( 'reports environment blend mode and base layer from the active session', () => {

			const manager = new XRManager( createRenderer() );
			manager._session = { environmentBlendMode: 'alpha-blend' };
			manager._glBaseLayer = { kind: 'base' };
