			expect( manager.getHand( 0 ) ).toBe( hand0 );
			expect( ray0 ).not.toBe( grip0 );
			expect( ray0 ).not.toBe( hand0 );

			const ray1 = manager.getController( 1 );
			expect( ray1 ).not.toBe( ray0 );
