	renderer.backend = { ...renderer.backend, ...overrides.backend };
	renderer._animation = overrides._animation || renderer._animation;
	renderer.gl = gl;

	return renderer;

}

function makeSession( overrides = {} ) {

	const listeners = new Map();

	const session = {
		enabledFeatures: [],
		environmentBlendMode: 'opaque',
		visibilityState: 'visible',
		renderState: { layers: [], baseLayer: null },
		addEventListener: jest.fn( ( type, listener ) => {

			if ( ! listeners.has( type ) ) listeners.set( type, [] );
			listeners.get( type ).push( listener );

		} ),
		removeEventListener: jest.fn( ( type, listener ) => {

			const entries = listeners.get( type );
			if ( entries === undefined ) return;
			const index = entries.indexOf( listener );
			if ( index !== - 1 ) entries.splice( index, 1 );

		} ),
		updateRenderState: jest.fn( function ( state ) {

			Object.assign( this.renderState, state );

		} ),
		requestReferenceSpace: jest.fn( async ( type ) => ( { type } ) ),
		emit( type, event = {} ) {

			const entries = listeners.get( type ) || [];
			for ( const listener of entries.slice() ) listener( { ...event, type } );

		},
		listenerCount( type ) {

			return ( listeners.get( type ) || [] ).length;

		}
	};

	return Object.assign( session, overrides );

}

function makeXRWebGLLayerClass() {

	class FakeXRWebGLLayer {

		constructor( session, gl, init ) {

			this.session = session;
			this.gl = gl;
			this.init = init;
			this.framebufferWidth = 2000;
			this.framebufferHeight = 1000;
			this.ignoreDepthValues = false;
			this.fixedFoveation = 1;
			this.framebuffer = { id: 'framebuffer' };
			this.getViewport = jest.fn( ( view ) => view.viewport );
			FakeXRWebGLLayer.instances.push( this );

		}

	}

	FakeXRWebGLLayer.instances = [];
	return FakeXRWebGLLayer;

}

function makeXRWebGLBindingClass() {

	class FakeXRWebGLBinding {

		constructor( session, gl ) {

			this.session = session;
			this.gl = gl;
			this.projectionLayer = {
				textureWidth: 1600,
				textureHeight: 900,
				ignoreDepthValues: false,
				fixedFoveation: 1
			};
			this.quadLayers = [];
			this.cylinderLayers = [];
			FakeXRWebGLBinding.instances.push( this );

		}

		createProjectionLayer( options ) {

			this.projectionLayerOptions = options;
			return this.projectionLayer;

		}

		createQuadLayer( options ) {

			const layer = { type: 'quad', options };
			this.quadLayers.push( layer );
			return layer;

		}

		createCylinderLayer( options ) {

			const layer = { type: 'cylinder', options };
			this.cylinderLayers.push( layer );
			return layer;

		}

	}

	FakeXRWebGLBinding.instances = [];
	return FakeXRWebGLBinding;

}

function makeXRGPUBindingClass() {

	class FakeXRGPUBinding {

		constructor( session, device ) {

			this.session = session;
			this.device = device;
			this.projectionLayer = {
				textureWidth: 2048,
				textureHeight: 1024,
				ignoreDepthValues: false,
				fixedFoveation: 1
			};
			FakeXRGPUBinding.instances.push( this );

		}

		getPreferredColorFormat() {

			return 'bgra8unorm';

		}

		createProjectionLayer( options ) {

			this.projectionLayerOptions = options;
			return this.projectionLayer;

		}

	}

	FakeXRGPUBinding.instances = [];
	return FakeXRGPUBinding;

}

function makeXRRigidTransformClass() {

	class FakeXRRigidTransform {

		constructor( position, orientation ) {

			this.position = position;
			this.orientation = orientation;

		}

	}

	return FakeXRRigidTransform;

}

function makeView( x = 0, width = 800, height = 600, position = [ 0, 0, 0 ] ) {

	const matrix = IDENTITY.slice();
	matrix[ 12 ] = position[ 0 ];
	matrix[ 13 ] = position[ 1 ];
	matrix[ 14 ] = position[ 2 ];

	return {
		transform: { matrix },
		projectionMatrix: new PerspectiveCamera( 70, 1, 0.2, 500 ).projectionMatrix.toArray(),
		viewport: { x, y: 0, width, height }
	};

}

