			renderer._animation.loop( 2, frame );
			expect( frame.getViewerPose ).toHaveBeenCalledTimes( 1 );
			expect( appLoop ).toHaveBeenCalledWith( 2, frame );
			expect( manager.getCamera().cameras ).toHaveLength( 0 );
