	'RGB8I', 'RGB16I', 'RGB32I', 'RGB565', 'RGB5_A1', 'RGB4', 'RGB9_E5', 'R11F_G11F_B10F',
	'RGBA32F', 'RGBA16F', 'SRGB8_ALPHA8', 'RGBA8', 'RGBA8_SNORM', 'RGBA4', 'RGBA8UI',
	'RGBA16UI', 'RGBA32UI', 'RGBA8I', 'RGBA16I', 'RGBA32I',
	'DEPTH_COMPONENT16', 'DEPTH_COMPONENT24', 'DEPTH_COMPONENT32F',
	'DEPTH24_STENCIL8', 'DEPTH32F_STENCIL8'
];

const GL = {};
GL_NAMES.forEach( ( name, i ) => {

	GL[ name ] = 0x2000 + i;

} );
GL.TEXTURE_CUBE_MAP_POSITIVE_X = 0x9000;

const NORM16 = {
	R16_EXT: 0xA001, R16_SNORM_EXT: 0xA002,
	RG16_EXT: 0xA003, RG16_SNORM_EXT: 0xA004,
	RGB16_EXT: 0xA005, RGB16_SNORM_EXT: 0xA006,
	RGBA16_EXT: 0xA007, RGBA16_SNORM_EXT: 0xA008
};

function createGL( overrides = {} ) {

	let textureId = 0;
	let framebufferId = 0;
	let bufferId = 0;

	return Object.assign( {}, GL, {
		createTexture: jest.fn( () => ( { texture: ++ textureId } ) ),
		deleteTexture: jest.fn(),
		createFramebuffer: jest.fn( () => ( { framebuffer: ++ framebufferId } ) ),
		deleteFramebuffer: jest.fn(),
		createBuffer: jest.fn( () => ( { buffer: ++ bufferId } ) ),
		deleteBuffer: jest.fn(),
		texParameteri: jest.fn(),
		texParameterf: jest.fn(),
		texStorage2D: jest.fn(),
		texStorage3D: jest.fn(),
		texSubImage2D: jest.fn(),
		texSubImage3D: jest.fn(),
		texImage2D: jest.fn(),
		compressedTexSubImage2D: jest.fn(),
		compressedTexSubImage3D: jest.fn(),
		generateMipmap: jest.fn(),
		bindBuffer: jest.fn(),
		bufferData: jest.fn(),
		readPixels: jest.fn(),
		getBufferSubData: jest.fn(),
		framebufferTexture2D: jest.fn(),
		framebufferTextureLayer: jest.fn(),
		blitFramebuffer: jest.fn(),
		copyTexSubImage2D: jest.fn(),
		copyTexSubImage3D: jest.fn(),
		bindRenderbuffer: jest.fn(),
		renderbufferStorage: jest.fn(),
		renderbufferStorageMultisample: jest.fn(),
		framebufferRenderbuffer: jest.fn()
	}, overrides );

}

function createBackend( gl ) {

	const store = new Map();
	const currentBoundFramebuffers = {};

	const state = {
		bindTexture: jest.fn(),
		unbindTexture: jest.fn(),
		pixelStorei: jest.fn(),
		getParameter: jest.fn( () => 0 ),
		bindFramebuffer: jest.fn( ( target, framebuffer ) => {

			currentBoundFramebuffers[ target ] = framebuffer;

		} ),
		currentBoundFramebuffers
	};

	const extensions = {
		get: jest.fn(),
		has: jest.fn( () => false )
	};

	const utils = {
		convert: jest.fn( ( value ) => value ),
		_clientWaitAsync: jest.fn( () => Promise.resolve() )
	};

	const backend = {
		gl,
		state,
		extensions,
		utils,
		capabilities: { getMaxAnisotropy: jest.fn( () => 16 ) },
		getDrawingBufferSize: jest.fn( () => ( { x: 800, y: 600 } ) ),
		set: jest.fn( ( texture, data ) => {

			store.set( texture, data );

		} ),
		get: jest.fn( ( texture ) => store.get( texture ) ),
		has: jest.fn( ( texture ) => store.has( texture ) ),
		delete: jest.fn( ( texture ) => {

			store.delete( texture );

		} ),
		_setFramebuffer: jest.fn()
	};

	return { backend, store, state, extensions, utils };

}

function createHarness( options = {} ) {

	const gl = createGL( options.gl );
	const env = createBackend( gl );
	const utils = new WebGLTextureUtils( env.backend );
	return { utils, gl, ...env };

}

function createTexture( overrides = {} ) {

	return Object.assign( {
		isTexture: true,
		colorSpace: NoColorSpace,
		flipY: true,
		premultiplyAlpha: false,
		unpackAlignment: 4,
		wrapS: ClampToEdgeWrapping,
		wrapT: ClampToEdgeWrapping,
		wrapR: ClampToEdgeWrapping,
		magFilter: LinearFilter,
		minFilter: LinearMipmapLinearFilter,
		type: UnsignedByteType,
		format: RGBAFormat,
		internalFormat: null,
		anisotropy: 1,
		generateMipmaps: true,
		mipmapsAutoUpdate: true,
		mipmaps: [],
		image: { width: 2, height: 2, data: new Uint8Array( 16 ) },
		layerUpdates: new Set(),
		clearLayerUpdates: jest.fn()
	}, overrides );

}

function seed( backend, texture, data ) {

	backend.set( texture, { textureGPU: { texture: 'gpu' }, ...data } );

	return backend.get( texture );

}

let warnSpy;

