			wrapT: MirroredRepeatWrapping,
			magFilter: NearestFilter,
			minFilter: NearestFilter
		} );

		utils.setTextureParameters( gl.TEXTURE_2D, texture );

		expect( state.pixelStorei ).toHaveBeenCalledWith( gl.UNPACK_FLIP_Y_WEBGL, true );
		expect( state.pixelStorei ).toHaveBeenCalledWith( gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true );
		expect( state.pixelStorei ).toHaveBeenCalledWith( gl.UNPACK_ALIGNMENT, 8 );
		expect( state.pixelStorei ).toHaveBeenCalledWith( gl.UNPACK_COLORSPACE_CONVERSION_WEBGL, gl.NONE );

		expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT );
		expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.MIRRORED_REPEAT );
		expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST );
		expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST );
		expect( gl.texParameteri ).not.toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_WRAP_R, expect.anything() );

	} );

	test( 'sets wrap R for 3D/array textures unless the texture is a layered array texture', () => {

		const { utils, gl } = createHarness();
		const texture = createTexture( { wrapR: RepeatWrapping } );

		utils.setTextureParameters( gl.TEXTURE_3D, texture );
		expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_3D, gl.TEXTURE_WRAP_R, gl.REPEAT );

		gl.texParameteri.mockClear();

