		utils.setTextureParameters( gl.TEXTURE_2D_ARRAY, arrayTexture );
		expect( gl.texParameteri ).not.toHaveBeenCalledWith( gl.TEXTURE_2D_ARRAY, gl.TEXTURE_WRAP_R, expect.anything() );

