		const texture = createTexture( { compareFunction: LessEqualCompare } );

		utils.setTextureParameters( gl.TEXTURE_2D, texture );

		expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_COMPARE_MODE, gl.COMPARE_REF_TO_TEXTURE );
		expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_COMPARE_FUNC, gl.LEQUAL );

