		utils.setTextureParameters( gl.TEXTURE_2D, createTexture( { magFilter: LinearFilter, minFilter: LinearMipmapLinearFilter, anisotropy: 8 } ) );
		expect( gl.texParameterf ).not.toHaveBeenCalled();

		const extensions = createHarness();
