		extensions.extensions.get.mockReturnValue( { TEXTURE_MAX_ANISOTROPY_EXT: 0xB001 } );
		extensions.utils.setTextureParameters( extensions.gl.TEXTURE_2D, createTexture( { magFilter: LinearFilter, minFilter: LinearMipmapLinearFilter, anisotropy: 1 } ) );
