describe( 'createTexture', () => {

	function createConvertImplementation( gl ) {

		const map = new Map( [
			[ RGBAFormat, gl.RGBA ],
			[ RGBFormat, gl.RGB ],
			[ RedFormat, gl.RED ],
			[ RGFormat, gl.RG ],
			[ RGBAIntegerFormat, gl.RGBA_INTEGER ],
			[ RedIntegerFormat, gl.RED_INTEGER ],
			[ UnsignedByteType, gl.UNSIGNED_BYTE ],
			[ FloatType, gl.FLOAT ],
			[ HalfFloatType, gl.HALF_FLOAT ],
			[ UnsignedIntType, gl.UNSIGNED_INT ],
			[ UnsignedShort4444Type, gl.UNSIGNED_SHORT_4_4_4_4 ],
			[ UnsignedShort5551Type, gl.UNSIGNED_SHORT_5_5_5_1 ],
			[ UnsignedInt248Type, gl.UNSIGNED_INT_24_8 ],
			[ DepthFormat, gl.DEPTH_COMPONENT ],
			[ DepthStencilFormat, gl.DEPTH_STENCIL ]
		] );

		return ( value ) => map.get( value );

	}

	test( 'creates and allocates a regular 2D texture', () => {

		const { utils, gl, backend, state, extensions } = createHarness();
		utils.backend.utils.convert.mockImplementation( createConvertImplementation( gl ) );

		const texture = createTexture( { format: RGBAFormat, type: UnsignedByteType, colorSpace: NoColorSpace } );
		utils.createTexture( texture, { levels: 1, width: 4, height: 8, depth: 1 } );

		const data = backend.get( texture );
		expect( data.textureGPU ).toBeDefined();
		expect( data.glTextureType ).toBe( gl.TEXTURE_2D );
		expect( data.glFormat ).toBe( gl.RGBA );
		expect( data.glType ).toBe( gl.UNSIGNED_BYTE );
		expect( data.glInternalFormat ).toBe( gl.RGBA8 );

		expect( gl.createTexture ).toHaveBeenCalledTimes( 1 );
		expect( state.bindTexture ).toHaveBeenCalledWith( gl.TEXTURE_2D, data.textureGPU );
		expect( gl.texStorage2D ).toHaveBeenCalledWith( gl.TEXTURE_2D, 1, gl.RGBA8, 4, 8 );
		expect( gl.texStorage3D ).not.toHaveBeenCalled();
		expect( gl.texParameteri ).toHaveBeenCalled();
		expect( extensions.get ).not.toHaveBeenCalledWith( 'EXT_texture_norm16' );

	} );

	test.each( [
		[ 'array texture', { isArrayTexture: true }, GL.TEXTURE_2D_ARRAY ],
		[ 'data array texture', { isDataArrayTexture: true }, GL.TEXTURE_2D_ARRAY ],
		[ 'compressed array texture', { isCompressedArrayTexture: true }, GL.TEXTURE_2D_ARRAY ],
		[ 'data 3D texture', { isData3DTexture: true }, GL.TEXTURE_3D ]
	] )( 'allocates a %s with texStorage3D', ( label, flags, expectedType ) => {

		const { utils, gl, backend } = createHarness();
		utils.backend.utils.convert.mockImplementation( createConvertImplementation( gl ) );

		const texture = createTexture( { ...flags, format: RGBAFormat, type: UnsignedByteType } );
		utils.createTexture( texture, { levels: 2, width: 4, height: 8, depth: 3 } );

		const data = backend.get( texture );
		expect( data.glTextureType ).toBe( expectedType );
		expect( gl.texStorage3D ).toHaveBeenCalledWith( expectedType, 2, gl.RGBA8, 4, 8, 3 );
		expect( gl.texStorage2D ).not.toHaveBeenCalled();

	} );

	test( 'allocates a cube texture with texStorage2D on the cube-map target', () => {

		const { utils, gl, backend } = createHarness();
		utils.backend.utils.convert.mockImplementation( createConvertImplementation( gl ) );

		const texture = createTexture( { isCubeTexture: true } );
		utils.createTexture( texture, { levels: 1, width: 16, height: 16, depth: 1 } );

		const data = backend.get( texture );
		expect( data.glTextureType ).toBe( gl.TEXTURE_CUBE_MAP );
		expect( gl.texStorage2D ).toHaveBeenCalledWith( gl.TEXTURE_CUBE_MAP, 1, gl.RGBA8, 16, 16 );

	} );

	test( 'does not allocate storage for video textures and forces a linear transfer', () => {

		const { utils, gl, backend } = createHarness();
		utils.backend.utils.convert.mockImplementation( createConvertImplementation( gl ) );

		const texture = createTexture( { isVideoTexture: true, colorSpace: SRGBColorSpace } );
		utils.createTexture( texture, { levels: 1, width: 4, height: 4, depth: 1 } );

		expect( backend.get( texture ).glInternalFormat ).toBe( gl.RGBA8 );
		expect( gl.texStorage2D ).not.toHaveBeenCalled();
		expect( gl.texStorage3D ).not.toHaveBeenCalled();

	} );

	test( 'uses an explicit internal format override', () => {

		const { utils, gl, backend } = createHarness();
		utils.backend.utils.convert.mockImplementation( createConvertImplementation( gl ) );

		const texture = createTexture( { internalFormat: 'RGBA16F' } );
		utils.createTexture( texture, { levels: 1, width: 4, height: 4, depth: 1 } );

		expect( backend.get( texture ).glInternalFormat ).toBe( gl.RGBA16F );
		expect( gl.texStorage2D ).toHaveBeenCalledWith( gl.TEXTURE_2D, 1, gl.RGBA16F, 4, 4 );

	} );

	test( 'wraps an external texture without creating or allocating a GL texture', () => {

		const { utils, gl, backend } = createHarness();
		const sourceTexture = { external: true };
		const texture = createTexture( { isExternalTexture: true, sourceTexture } );

		utils.createTexture( texture, { levels: 1, width: 4, height: 4, depth: 1 } );

		const data = backend.get( texture );
		expect( data.textureGPU ).toBe( sourceTexture );
		expect( data.glTextureType ).toBe( gl.TEXTURE_2D );
		expect( data.glFormat ).toBeUndefined();
		expect( data.glType ).toBeUndefined();
		expect( data.glInternalFormat ).toBeUndefined();
		expect( gl.createTexture ).not.toHaveBeenCalled();
		expect( gl.texStorage2D ).not.toHaveBeenCalled();
		expect( gl.texStorage3D ).not.toHaveBeenCalled();

	} );

} );

describe( 'copyBufferToTexture', () => {

