		expect( gl.deleteRenderbuffer ).toHaveBeenCalledWith( renderContextData.msaaRenderbuffers[ 0 ] );
		expect( gl.deleteRenderbuffer ).toHaveBeenCalledWith( renderContextData.msaaRenderbuffers[ 1 ] );

		expect( renderContextData.renderBufferStorageSetup ).toBeUndefined();
		expect( renderContextData.framebuffers ).toBeUndefined();
		expect( renderContextData.depthRenderbuffer ).toBeUndefined();
		expect( renderContextData.stencilRenderbuffer ).toBeUndefined();
