				hasPositionAttribute: true,
				vertexShader: 'void main() { gl_Position = vec4( 0.0 ); }',
				fragmentShader: 'void main() { gl_FragColor = vec4( 1.0 ); }',
				cacheKey: 'ignored'
			}, { cacheKey: 'material-cache-key' } );

			const [ vertexShader, fragmentShader ] = result.shaders;

			expect( result.gl.createProgram ).toHaveBeenCalledTimes( 1 );
			expect( result.gl.createShader ).toHaveBeenNthCalledWith( 1, result.gl.VERTEX_SHADER );
			expect( result.gl.createShader ).toHaveBeenNthCalledWith( 2, result.gl.FRAGMENT_SHADER );
			expect( vertexShader.source ).toMatch( /^#version 300 es\n/ );
			expect( vertexShader.source ).toContain( '#define SHADER_TYPE TestMaterial' );
			expect( vertexShader.source ).toContain( '#define SHADER_NAME TestMaterial' );
			expect( vertexShader.source ).toContain( '#define ENABLED 1' );
			expect( vertexShader.source ).toContain( '#define LABEL visible' );
			expect( vertexShader.source ).not.toContain( 'OMITTED' );
			expect( vertexShader.source ).toContain( 'precision highp float;' );
			expect( vertexShader.source ).toContain( '#define HIGH_PRECISION' );
			expect( vertexShader.source ).toContain( '#define attribute in' );
			expect( vertexShader.source ).toContain( '#define varying out' );
			expect( vertexShader.source ).toContain( 'uniform mat4 modelViewMatrix;' );
			expect( vertexShader.source.endsWith( 'void main() { gl_Position = vec4( 0.0 ); }' ) ).toBe( true );
			expect( fragmentShader.source ).toMatch( /^#version 300 es\n/ );
			expect( fragmentShader.source ).toContain( 'layout(location = 0) out highp vec4 pc_fragColor;' );
			expect( fragmentShader.source ).toContain( '#define gl_FragColor pc_fragColor' );
			expect( fragmentShader.source.endsWith( 'void main() { gl_FragColor = vec4( 1.0 ); }' ) ).toBe( true );
			expect( result.gl.attachShader ).toHaveBeenNthCalledWith( 1, result.program, vertexShader );
			expect( result.gl.attachShader ).toHaveBeenNthCalledWith( 2, result.program, fragmentShader );
			expect( result.gl.bindAttribLocation ).toHaveBeenCalledWith( result.program, 0, 'position' );
			expect( result.gl.linkProgram ).toHaveBeenCalledWith( result.program );
			expect( result.program.program ).toBe( result.program );
			expect( result.program.type ).toBe( 'TestMaterial' );
			expect( result.program.name ).toBe( 'TestMaterial' );
			expect( result.program.cacheKey ).toBe( 'material-cache-key' );
			expect( result.program.usedTimes ).toBe( 1 );
			expect( result.program.vertexShader ).toBe( vertexShader );
			expect( result.program.fragmentShader ).toBe( fragmentShader );

		} );

		it( 'supports raw shader materials without adding built-in precision or GLSL conversion prefixes', () => {

			const result = compileProgram( {
