			expect( vertexShader.source ).toContain( '#define SHADER_TYPE TestMaterial' );
			expect( vertexShader.source ).toContain( '#define RAW_ONLY true' );
			expect( vertexShader.source ).not.toContain( 'DISCARD_ME' );
			expect( vertexShader.source ).not.toContain( 'precision highp float' );
			expect( vertexShader.source ).not.toContain( '#define attribute in' );
			expect( vertexShader.source ).not.toContain( 'uniform mat4 modelViewMatrix;' );
			expect( fragmentShader.source ).not.toContain( 'pc_fragColor' );
			expect( fragmentShader.source ).not.toContain( 'precision highp float' );
			expect( result.gl.bindAttribLocation ).toHaveBeenCalledWith( result.program, 0, 'position' );

		} );

		it( 'uses an explicit index-zero attribute in preference to the position attribute', () => {

			const result = compileProgram( {
				index0AttributeName: 'customPosition',
				hasPositionAttribute: true
			} );

			expect( result.gl.bindAttribLocation ).toHaveBeenCalledTimes( 1 );
			expect( result.gl.bindAttribLocation ).toHaveBeenCalledWith( result.program, 0, 'customPosition' );

		} );

		it( 'does not bind attribute zero when no attribute is requested', () => {

			const result = compileProgram();

			expect( result.gl.bindAttribLocation ).not.toHaveBeenCalled();

		} );

	} );
