		beginOcclusionQuery: jest.fn(),
		endOcclusionQuery: jest.fn()
	};

}

function makeComputePassEncoder() {

	return {
		end: jest.fn(),
		setPipeline: jest.fn(),
		setBindGroup: jest.fn(),
		dispatchWorkgroups: jest.fn(),
		dispatchWorkgroupsIndirect: jest.fn()
	};

}

function makeCommandEncoder() {

	const renderPass = makeRenderPassEncoder();
	const computePass = makeComputePassEncoder();
	const commandBuffer = { commandBuffer: true };
	const encoder = {
		renderPass,
		computePass,
		commandBuffer,
		beginRenderPass: jest.fn( () => renderPass ),
		beginComputePass: jest.fn( () => computePass ),
		copyTextureToTexture: jest.fn(),
		copyBufferToBuffer: jest.fn(),
		resolveQuerySet: jest.fn(),
		finish: jest.fn( () => commandBuffer )
	};

	return encoder;

}

function makeDevice( { features = [], limits = {} } = {} ) {

	const featureSet = new Set( features );
	let resolveLost;
	const lost = new Promise( resolve => {

		resolveLost = resolve;

	} );

	const device = {
		features: { has: jest.fn( name => featureSet.has( name ) ) },
		limits: {
			maxUniformBufferBindingSize: 65536,
			maxComputeWorkgroupsPerDimension: 65535,
			...limits
		},
		lost,
		queue: { submit: jest.fn(), writeBuffer: jest.fn(), writeTexture: jest.fn() },
		onuncapturederror: null,
		destroy: jest.fn(),
		createBuffer: jest.fn( () => makeGPUResource() ),
		createTexture: jest.fn( () => makeGPUResource() ),
		createCommandEncoder: jest.fn( () => makeCommandEncoder() ),
		createQuerySet: jest.fn( () => makeGPUResource() ),
		createShaderModule: jest.fn( () => ( { module: true } ) ),
		_resolveLost: resolveLost
	};

	return device;

}

function makeRenderer( overrides = {} ) {

	const canvas = {
		setAttribute: jest.fn(),
		getContext: jest.fn()
	};

	const canvasTarget = {
		isDefaultCanvasTarget: true,
		domElement: canvas,
		colorTexture: {},
		depthTexture: {}
	};

	const renderer = {
		xr: { enabled: false },
		alpha: true,
		depth: false,
		stencil: false,
		currentSamples: 0,
		reversedDepthBuffer: false,
		_samples: 4,
		onDeviceLost: jest.fn(),
		onError: jest.fn(),
		getCanvasTarget: jest.fn( () => canvasTarget ),
		getClearColor: jest.fn( target => {

			target.setRGB( 0.2, 0.4, 0.6 );
			target.a = 0.5;
			return target;

		} ),
		getClearDepth: jest.fn( () => 0.25 ),
		getClearStencil: jest.fn( () => 7 ),
		getPixelRatio: jest.fn( () => 2 ),
		...overrides
	};

	return { renderer, canvas, canvasTarget };

}

function attachRenderer( backend, renderer, device ) {

	backend.renderer = renderer;
	backend.device = device;
	backend.utils.getPreferredCanvasFormat = jest.fn( () => 'bgra8unorm' );

}

function makeCanvasContext() {

	const currentTexture = makeGPUResource();
	const context = {
		configure: jest.fn(),
		getCurrentTexture: jest.fn( () => currentTexture ),
		currentTexture
	};

	return context;

}

