	test( 'prepares and completes a default color render pass with clear, viewport, and scissor state', () => {

		const context = makeCanvasContext();
		const backend = new WebGPUBackend( { context } );
		const device = makeDevice();
		const { renderer } = makeRenderer();
		attachRenderer( backend, renderer, device );
		const submitted = [];
		device.queue.submit.mockImplementation( list => submitted.push( [ ...list ] ) );

		const renderContext = {
			id: 17,
			textures: null,
			occlusionQueryCount: 0,
			sampleCount: 0,
			clearColor: true,
			clearColorValue: { r: 0.9, g: 0.8, b: 0.7, a: 0.6 },
			depth: false,
			stencil: false,
			viewport: true,
			viewportValue: { x: 1, y: 2, width: 30, height: 40, minDepth: 0, maxDepth: 1 },
			scissor: true,
			scissorValue: { x: 3, y: 4, width: 5, height: 6 }
		};

		backend.beginRender( renderContext );

		const data = backend.get( renderContext );
		const descriptor = data.descriptor;
		expect( data.currentPass ).toBe( device.createCommandEncoder.mock.results[ 0 ].value.renderPass );
		expect( descriptor.colorAttachments ).toHaveLength( 1 );
		expect( descriptor.colorAttachments[ 0 ].view ).toBe( context.currentTexture.createView.mock.results[ 0 ].value );
		expect( descriptor.colorAttachments[ 0 ].loadOp ).toBe( 'clear' );
		expect( descriptor.colorAttachments[ 0 ].storeOp ).toBe( 'store' );
		expect( descriptor.colorAttachments[ 0 ].clearValue ).toEqual( { r: 0.9, g: 0.8, b: 0.7, a: 0.6 } );
		expect( data.currentPass.setViewport ).toHaveBeenCalledWith( 1, 2, 30, 40, 0, 1 );
		expect( data.currentPass.setScissorRect ).toHaveBeenCalledWith( 3, 4, 5, 6 );

		backend.finishRender( renderContext );

