const globals = new Map();

function setGlobal( name, value ) {

	if ( globals.has( name ) === false ) {

		globals.set( name, Object.getOwnPropertyDescriptor( globalThis, name ) );

	}

	Object.defineProperty( globalThis, name, {
		configurable: true,
		writable: true,
		value
	} );

}

function restoreGlobals() {

	for ( const [ name, descriptor ] of globals ) {

		if ( descriptor === undefined ) delete globalThis[ name ];
		else Object.defineProperty( globalThis, name, descriptor );

	}

	globals.clear();

}

function createFeatures( supported = [], needed = [] ) {

	const featureSet = new Set( supported );
	const belongs = [ ...needed, ...supported ].filter( value => typeof value === 'string' );

	return {
		has: jest.fn( name => featureSet.has( name ) ),
		_add( name ) {

			featureSet.add( name );
			if ( belongs.includes( name ) === false ) belongs.push( name );

		}
	};

}

function createDevice( { supported = [], limits = {} } = {} ) {

