		sampleData: { samples: 1, primarySamples: 1, isMSAA: false },
		data: new Map(),
		get( object ) {

			let value = this.data.get( object );

			if ( value === undefined ) {

				value = {};
				this.data.set( object, value );

			}

			return value;

		},
		delete( object ) {

