let WebGPUTextureUtils;
let getFormat;
let Texture, DataTexture, Data3DTexture, DataArrayTexture, CubeTexture, DepthTexture;
let CompressedTexture, HTMLTexture, FramebufferTexture, ExternalTexture;
let C;
let GPU;

const savedGlobals = {};

function createSpy( implementation = () => undefined ) {

	const spy = ( ...args ) => {

		spy.calls.push( args );
		return implementation( ...args );

	};

	spy.calls = [];
	spy.mockImplementation = ( fn ) => {

		implementation = fn;
		return spy;

	};

	spy.mockReturnValue = ( value ) => spy.mockImplementation( () => value );
	spy.mockResolvedValue = ( value ) => spy.mockImplementation( () => Promise.resolve( value ) );

	return spy;

}

function createBackend() {

	let textureCount = 0;

	const backend = {
		drawSize: { width: 320, height: 240 },
		sampleData: { samples: 1, primarySamples: 1, isMSAA: false },
		data: new Map(),
		get( object ) {

			let value = this.data.get( object );

			if ( value === undefined ) {

				value = {};
				this.data.set( object, value );

			}

			return value;

		},
		delete( object ) {

			this.data.delete( object );

		},
		hasCompatibility: createSpy( () => false ),
		getDrawingBufferSize: createSpy( () => ( { ...backend.drawSize } ) ),
	};

	backend.utils = {
		getTextureSampleData: createSpy( () => ( { ...backend.sampleData } ) ),
		getSampleCount: createSpy( ( samples ) => samples >= 4 ? 4 : 1 ),
		getPreferredCanvasFormat: createSpy( () => GPU.GPUTextureFormat.BGRA8Unorm ),
		getCurrentColorFormat: createSpy( () => GPU.GPUTextureFormat.RGBA8Unorm ),
	};

	backend.device = {
		features: { has: createSpy( () => false ) },
		queue: {
			submit: createSpy(),
			writeTexture: createSpy(),
			copyExternalImageToTexture: createSpy(),
			writeBuffer: createSpy(),
		},
		createTexture: createSpy( ( descriptor ) => ( {
			id: textureCount ++,
			descriptor,
			sampleCount: descriptor.sampleCount,
			destroy: createSpy(),
			createView: createSpy( () => ( { view: textureCount } ) ),
		} ) ),
		createSampler: createSpy( ( descriptor ) => ( { descriptor: { ...descriptor }, destroy: createSpy() } ) ),
		createBuffer: createSpy(),
		createCommandEncoder: createSpy(),
	};

	backend.renderer = {
		currentSamples: 1,
		reversedDepthBuffer: false,
		domElement: { requestPaint: createSpy() },
		getCanvasTarget: createSpy( () => ( { colorTexture: new Texture(), depthTexture: new DepthTexture( 1, 1 ) } ) ),
	};

	return backend;

}

function makeTexture( overrides = {} ) {

	return {
		format: C.RGBAFormat,
		type: C.UnsignedByteType,
		normalized: false,
		colorSpace: C.NoColorSpace,
		isCompressedTexture: false,
		isCompressedArrayTexture: false,
		...overrides,
	};

}

