describe( 'WebGPUTextureUtils samplers', () => {

	let backend;
	let utils;

	beforeEach( () => {

		backend = createBackend();
		utils = new WebGPUTextureUtils( backend );

	} );

	test( 'creates and reuses a sampler using texture state and anisotropy', () => {

		const texture = new Texture();
		texture.minFilter = C.LinearMipmapLinearFilter;
		texture.magFilter = C.LinearFilter;
		texture.wrapS = C.RepeatWrapping;
		texture.wrapT = C.MirroredRepeatWrapping;
		texture.anisotropy = 8;

		const binding = { texture, textureNode: { isSampleCompare: () => false } };
		const key = utils.updateSampler( binding );

		expect( key ).toBe( `${C.LinearMipmapLinearFilter}-${C.LinearFilter}-${C.RepeatWrapping}-${C.MirroredRepeatWrapping}-0-8-0-0` );
		expect( backend.device.createSampler.calls.length ).toBe( 1 );

		const descriptor = backend.device.createSampler.calls[ 0 ][ 0 ];
		expect( descriptor.addressModeU ).toBe( GPU.GPUAddressMode.Repeat );
		expect( descriptor.addressModeV ).toBe( GPU.GPUAddressMode.MirrorRepeat );
		expect( descriptor.addressModeW ).toBe( GPU.GPUAddressMode.ClampToEdge );
		expect( descriptor.magFilter ).toBe( GPU.GPUFilterMode.Linear );
		expect( descriptor.minFilter ).toBe( GPU.GPUFilterMode.Linear );
		expect( descriptor.mipmapFilter ).toBe( GPU.GPUFilterMode.Linear );
		expect( descriptor.maxAnisotropy ).toBe( 8 );
		expect( descriptor.compare ).toBeUndefined();

		const secondBinding = { texture, textureNode: { isSampleCompare: () => false } };
		expect( utils.updateSampler( secondBinding ) ).toBe( key );
		expect( backend.device.createSampler.calls.length ).toBe( 1 );
		expect( backend.get( binding ).sampler ).toBe( backend.get( secondBinding ).sampler );

		utils.destroySampler( binding );
		expect( utils._samplerCache.size ).toBe( 1 );
		utils.destroySampler( secondBinding );
		expect( utils._samplerCache.size ).toBe( 0 );

	} );

	test( 'uses comparison sampling for depth textures when supported', () => {

		backend.hasCompatibility = createSpy( () => true );
		const texture = new DepthTexture( 2, 2 );
		texture.compareFunction = C.LessCompare;
		const binding = { texture, textureNode: { isSampleCompare: () => true } };

		const key = utils.updateSampler( binding );
		const descriptor = backend.device.createSampler.calls[ 0 ][ 0 ];

		expect( key ).toContain( `-1-${C.LessCompare}` );
		expect( descriptor.compare ).toBe( 'less' );
		expect( backend.device.createSampler.calls.length ).toBe( 1 );

	} );

	test( 'forces nearest filtering for depth textures without comparison', () => {

		backend.hasCompatibility = createSpy( () => false );
		const texture = new DepthTexture( 2, 2 );
		texture.magFilter = C.LinearFilter;
		texture.minFilter = C.LinearMipmapLinearFilter;
		texture.anisotropy = 16;

		utils.updateSampler( { texture, textureNode: { isSampleCompare: () => true } } );
		const descriptor = backend.device.createSampler.calls[ 0 ][ 0 ];

		expect( descriptor.magFilter ).toBe( GPU.GPUFilterMode.Nearest );
		expect( descriptor.minFilter ).toBe( GPU.GPUFilterMode.Nearest );
		expect( descriptor.mipmapFilter ).toBe( GPU.GPUFilterMode.Nearest );
		expect( descriptor.maxAnisotropy ).toBe( 1 );
		expect( descriptor.compare ).toBeUndefined();

	} );

} );

describe( 'WebGPUTextureUtils texture creation', () => {

