		const texture = new DataTexture( new Uint8Array( 4 ), 2, 2 );
		texture.name = 'albedo';

		utils.createTexture( texture, { width: 8, height: 4, depth: 2, levels: 3 } );

		const descriptor = backend.device.createTexture.calls[ 0 ][ 0 ];
		const data = backend.get( texture );

		expect( descriptor.label ).toBe( 'albedo' );
		expect( descriptor.size ).toEqual( { width: 8, height: 4, depthOrArrayLayers: 2 } );
		expect( descriptor.mipLevelCount ).toBe( 3 );
		expect( descriptor.sampleCount ).toBe( 1 );
		expect( descriptor.dimension ).toBe( GPU.GPUTextureDimension.TwoD );
		expect( descriptor.format ).toBe( GPU.GPUTextureFormat.RGBA8Unorm );
		expect( descriptor.usage ).toBe( 1 | 2 | 4 | 16 );
		expect( data.initialized ).toBe( true );
		expect( data.format ).toBe( GPU.GPUTextureFormat.RGBA8Unorm );
		expect( data.textureDescriptorGPU ).toBe( descriptor );

