describe( 'WebGPUTextureUtils updateTexture', () => {

	let backend;
	let utils;

	beforeEach( () => {

		backend = createBackend();
		utils = new WebGPUTextureUtils( backend );

	} );

	test( 'uploads each mip level of a data texture', () => {

		const texture = new DataTexture( new Uint8Array( 16 ), 2, 2 );
		utils.createTexture( texture, { width: 2, height: 2 } );
		const mipmaps = [
			{ data: new Uint8Array( 16 ), width: 2, height: 2 },
			{ data: new Uint8Array( 4 ), width: 1, height: 1 },
		];
		texture.mipmaps = mipmaps;
		texture.version = 7;
		const copy = createSpy();
		utils._copyBufferToTexture = copy;

		utils.updateTexture( texture, { image: texture.image } );

		expect( copy.calls.length ).toBe( 2 );
		expect( copy.calls[ 0 ][ 0 ] ).toBe( mipmaps[ 0 ] );
		expect( copy.calls[ 0 ][ 6 ] ).toBe( 0 );
		expect( copy.calls[ 1 ][ 0 ] ).toBe( mipmaps[ 1 ] );
		expect( copy.calls[ 1 ][ 6 ] ).toBe( 1 );
		expect( backend.get( texture ).version ).toBe( 7 );

	} );

	test( 'uploads only marked layers of an array texture and clears the update set', () => {

		const texture = new DataArrayTexture( new Uint8Array( 48 ), 2, 2, 3 );
