describe( 'WebGPUTextureUtils copyTextureToBuffer', () => {

	test( 'copies to a padded read buffer and returns tightly packed typed data', async () => {

		const backend = createBackend();
		const utils = new WebGPUTextureUtils( backend );
		const texture = new Texture();
		const textureGPU = { gpu: true };
		backend.get( texture ).texture = textureGPU;
		backend.get( texture ).textureDescriptorGPU = { format: GPU.GPUTextureFormat.RGBA8Unorm };

		const mapped = new Uint8Array( 512 );
		mapped.fill( 9, 0, 12 );
		mapped.fill( 7, 256, 268 );
		const readBuffer = {
			mapAsync: createSpy( () => Promise.resolve() ),
			getMappedRange: createSpy( () => mapped.buffer ),
			destroy: createSpy(),
		};
		let copyCall;
		const commandBuffer = { command: true };
		backend.device.createBuffer = createSpy( ( descriptor ) => {

			expect( descriptor.size ).toBe( 512 );
			expect( descriptor.usage ).toBe( 1 | 8 );
			return readBuffer;

		} );
		backend.device.createCommandEncoder = createSpy( () => ( {
			copyTextureToBuffer: createSpy( ( source, destination, extent ) => {

				copyCall = {
					texture: source.texture,
					origin: { ...source.origin },
					buffer: destination.buffer,
					bytesPerRow: destination.bytesPerRow,
					width: extent.width,
					height: extent.height,
				};

			} ),
			finish: createSpy( () => commandBuffer ),
		} ) );

		const result = await utils.copyTextureToBuffer( texture, 1, 2, 3, 2, 4 );

		expect( copyCall ).toEqual( {
			texture: textureGPU,
			origin: { x: 1, y: 2, z: 4 },
			buffer: readBuffer,
			bytesPerRow: 256,
			width: 3,
			height: 2,
		} );
		expect( backend.device.queue.submit.calls[ 0 ][ 0 ] ).toEqual( [ commandBuffer ] );
		expect( readBuffer.mapAsync.calls[ 0 ][ 0 ] ).toBe( GPUMapMode.READ );
		expect( readBuffer.destroy.calls.length ).toBe( 1 );
		expect( result ).toBeInstanceOf( Uint8Array );
		expect( result.length ).toBe( 24 );
		expect( Array.from( result.slice( 0, 12 ) ) ).toEqual( new Array( 12 ).fill( 9 ) );
		expect( Array.from( result.slice( 12, 24 ) ) ).toEqual( new Array( 12 ).fill( 7 ) );

	} );

} );

