			env: {},
			activeScriptNames: [],
			run: jest.fn(),
			invalidateScript: jest.fn()
		},
		lastContentWidth: '40%',
		lastHandledHash: '',
		lastPreviewHeight: null,
		debugLanguage: 'WGSL',
		debugStage: 'fragment',
		scene: null,
		camera: null
	};

	return Object.assign( guide, overrides );

}

function createManager( overrides = {} ) {

	const guide = createGuide( overrides );
	return { guide, manager: new PlaygroundManager( guide ) };

}

function createFetchResponse( { ok = true, contentType = 'application/javascript', text = '' } = {} ) {

	return {
		ok,
		headers: { get: ( name ) => ( name === 'content-type' ? contentType : null ) },
		text: async () => text
	};

}

async function decodeHash( hash ) {

	const base64 = hash.replace( /^playground[=\/]/, '' ).split( '&' )[ 0 ];
	return JSON.parse( await decompressString( base64 ) );

}

