	return dom.tabsBar.querySelectorAll( '.playground-tab-label' ).find( label => label.textContent === name ) || null;

}

describe( 'PlaygroundManager.startRenameTab', () => {

	test( 'never renames the main tab', () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		manager.playgroundTabs = [ { name: 'main', code: '// main\n' } ];
		manager.activePlaygroundTabName = 'main';
		manager.renderPlaygroundTabs();

		manager.startRenameTab( 'main', findTabLabel( guide.dom, 'main' ) );

		expect( guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' ) ).toBeNull();

	} );

	test( 'never renames a read-only tab', () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		manager.playgroundTabs = [ { name: 'helper', code: 'export {};', readOnly: true } ];
		manager.activePlaygroundTabName = 'helper';
		manager.renderPlaygroundTabs();

		manager.startRenameTab( 'helper', findTabLabel( guide.dom, 'helper' ) );

		expect( guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' ) ).toBeNull();

	} );

	test( 'applies a trimmed, lowercased rename on Enter', async () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		manager.playgroundTabs = [
			{ name: 'main', code: '// main\n' },
			{ name: 'alpha', code: 'export const a = 1;' }
		];
		manager.activePlaygroundTabName = 'alpha';
		manager.renderPlaygroundTabs();
		guide.codeEditor.value = 'export const a = 2;';

		manager.startRenameTab( 'alpha', findTabLabel( guide.dom, 'alpha' ) );

		const input = guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' );
		expect( input ).not.toBeNull();
		expect( input.value ).toBe( 'alpha' );

		input.value = '  Helper  ';
		input.onkeydown( { key: 'Enter' } );
		await flushAsync();

		expect( manager.playgroundTabs.map( tab => tab.name ) ).toEqual( [ 'main', 'helper' ] );
		expect( manager.playgroundTabs[ 1 ].code ).toBe( 'export const a = 2;' );
		expect( manager.activePlaygroundTabName ).toBe( 'helper' );
		expect( guide.runner.run ).toHaveBeenCalled();
		expect( guide.historyManager.pushState ).toHaveBeenCalledTimes( 1 );
		expect( findTabLabel( guide.dom, 'helper' ) ).not.toBeNull();
		expect( guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' ) ).toBeNull();

	} );

	test( 'rejects names that are not valid identifiers and restores the label', () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		manager.playgroundTabs = [ { name: 'alpha', code: 'export {};' } ];
		manager.activePlaygroundTabName = 'alpha';
		manager.renderPlaygroundTabs();

		manager.startRenameTab( 'alpha', findTabLabel( guide.dom, 'alpha' ) );

		const input = guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' );
		input.value = '2 bad-name';
		input.onkeydown( { key: 'Enter' } );

		expect( manager.playgroundTabs[ 0 ].name ).toBe( 'alpha' );
		expect( guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' ) ).toBeNull();
		expect( findTabLabel( guide.dom, 'alpha' ) ).not.toBeNull();
		expect( guide.historyManager.pushState ).not.toHaveBeenCalled();

	} );

	test( 'rejects duplicate tab names', () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		manager.playgroundTabs = [
			{ name: 'alpha', code: 'export const a = 1;' },
			{ name: 'beta', code: 'export const b = 1;' }
		];
		manager.activePlaygroundTabName = 'alpha';
		manager.renderPlaygroundTabs();

		manager.startRenameTab( 'alpha', findTabLabel( guide.dom, 'alpha' ) );

		const input = guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' );
		input.value = 'beta';
		input.onkeydown( { key: 'Enter' } );

		expect( manager.playgroundTabs.map( tab => tab.name ) ).toEqual( [ 'alpha', 'beta' ] );
		expect( guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' ) ).toBeNull();

	} );

	test( 'cancels the rename on Escape', () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		manager.playgroundTabs = [ { name: 'alpha', code: 'export {};' } ];
		manager.activePlaygroundTabName = 'alpha';
		manager.renderPlaygroundTabs();

		manager.startRenameTab( 'alpha', findTabLabel( guide.dom, 'alpha' ) );

		const input = guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' );
		input.value = 'renamed';
		input.onkeydown( { key: 'Escape' } );

		expect( manager.playgroundTabs[ 0 ].name ).toBe( 'alpha' );
		expect( guide.dom.tabsBar.querySelector( '.playground-tab-rename-input' ) ).toBeNull();
		expect( findTabLabel( guide.dom, 'alpha' ) ).not.toBeNull();
		expect( guide.historyManager.pushState ).not.toHaveBeenCalled();

	} );

} );

describe( 'PlaygroundManager.runPlayground', () => {

	test( 'does nothing before any tabs exist', () => {

		const { guide, manager } = createManager();

		manager.runPlayground();

		expect( guide.runner.run ).not.toHaveBeenCalled();

	} );

	test( 'drops virtual scripts whose tab was removed but keeps real and main scripts', () => {

		const { guide, manager } = createManager();
		guide.runner.scripts = {
			__main__: { url: null },
			stale: { url: null },
			remote: { url: './js/imports/scripts/remote.js' }
		};
		manager.playgroundTabs = [ { name: 'main', code: '// main\n' } ];

		manager.runPlayground();

		expect( guide.runner.invalidateScript ).toHaveBeenCalledWith( 'stale' );
		expect( guide.runner.scripts ).not.toHaveProperty( 'stale' );
		expect( guide.runner.scripts ).toHaveProperty( '__main__' );
		expect( guide.runner.scripts ).toHaveProperty( 'remote' );

	} );

	test( 'registers editable script tabs as virtual scripts', () => {

		const { guide, manager } = createManager();
		manager.playgroundTabs = [
			{ name: 'main', code: '// main\n' },
			{ name: 'helper', code: 'export const helper = 1;' },
			{ name: 'locked', code: 'export const locked = 1;', readOnly: true }
		];

		manager.runPlayground();

		expect( guide.runner.invalidateScript ).toHaveBeenCalledWith( 'helper' );
		expect( guide.runner.scripts.helper ).toEqual( {
			url: null,
			text: 'export const helper = 1;',
			instance: null,
			promise: null,
			dependencies: []
		} );
		expect( guide.runner.scripts ).not.toHaveProperty( 'locked' );
		expect( guide.runner.run ).toHaveBeenCalledWith( '// main\n' );

	} );

	test( 'falls back to the first tab when no main tab exists', () => {

		const { guide, manager } = createManager();
		manager.playgroundTabs = [ { name: 'first', code: 'export const first = 1;' } ];

		manager.runPlayground();

		expect( guide.runner.run ).toHaveBeenCalledWith( 'export const first = 1;' );

	} );

} );

describe( 'PlaygroundManager.getDebugTarget', () => {

	test( 'prefers the debug export of the main script', () => {

		const { guide, manager } = createManager();
		const mainDebug = { name: 'main-debug' };
		const otherDebug = { name: 'other-debug' };
		guide.runner.scripts = {
			__main__: { instance: { debug: () => mainDebug } },
			helper: { instance: { debug: () => otherDebug } }
		};
		guide.runner.activeScriptNames = [ 'helper' ];

		expect( manager.getDebugTarget() ).toBe( mainDebug );

	} );

	test( 'falls back to scripts reported as active', () => {

		const { guide, manager } = createManager();
		const otherDebug = { name: 'other-debug' };
		guide.runner.scripts = {
			helper: { instance: { debug: () => otherDebug } }
		};
		guide.runner.activeScriptNames = [ 'helper' ];

		expect( manager.getDebugTarget() ).toBe( otherDebug );

	} );

	test( 'returns null when no script exposes debug()', () => {

		const { guide, manager } = createManager();
		guide.runner.scripts = {
			__main__: { instance: { debug: 'not-a-function' } },
			helper: { instance: {} }
		};
		guide.runner.activeScriptNames = [ 'helper' ];

		expect( manager.getDebugTarget() ).toBeNull();

	} );

} );

describe( 'PlaygroundManager.updateDebugWGSL', () => {

	function attachDebug( guide, debugData ) {

		guide.runner.scripts.__main__ = { instance: { debug: () => debugData } };

	}

	test( 'does nothing when the playground is inactive', () => {

		const { guide, manager } = createManager();

		manager.updateDebugWGSL();

		expect( guide.debugCodeEditor.setValue ).not.toHaveBeenCalled();
		expect( guide.layoutManager.updateVResizerIcons ).not.toHaveBeenCalled();

	} );

	test( 'explains that no debug target is available and collapses the preview', () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		guide.dom.previewSection.style.height = '50%';

		manager.updateDebugWGSL();

		expect( guide.debugCodeEditor.setValue ).toHaveBeenCalledWith( 'No debug() function exported or debug target object found.' );
		expect( guide.dom.previewSection.style.height ).toBe( '100%' );
		expect( guide.lastPreviewHeight ).toBe( '50%' );
		expect( guide.layoutManager.updateVResizerIcons ).toHaveBeenCalledWith( '100%' );
		expect( guide.codeEditor.layout ).toHaveBeenCalled();
		expect( guide.debugCodeEditor.layout ).toHaveBeenCalled();

	} );

	test( 'shows the fragment shader returned for an explicit debug target', async () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		const scene = { name: 'scene' };
		const camera = { name: 'camera' };
		const object = { name: 'object' };
		attachDebug( guide, { scene, camera, object } );
		guide.renderer.debug.getShaderAsync.mockResolvedValue( { vertexShader: 'void main() {}', fragmentShader: 'frag-main' } );

		manager.updateDebugWGSL();
		await flushAsync();

		expect( guide.renderer.debug.getShaderAsync ).toHaveBeenCalledWith( scene, camera, object );
		expect( guide.debugCodeEditor.setValue ).toHaveBeenCalledWith( 'frag-main' );

	} );

	test( 'shows the vertex shader when the vertex debug stage is selected', async () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true, debugStage: 'vertex' } );
		const object = { name: 'object' };
		attachDebug( guide, object );
		guide.renderer.debug.getShaderAsync.mockResolvedValue( { vertexShader: 'vertex-main', fragmentShader: 'frag-main' } );

		manager.updateDebugWGSL();
		await flushAsync();

		expect( guide.renderer.debug.getShaderAsync ).toHaveBeenCalledWith( guide.scene, guide.camera, object );
		expect( guide.debugCodeEditor.setValue ).toHaveBeenCalledWith( 'vertex-main' );

	} );

	test( 'uses the WebGL renderer when GLSL is selected', async () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true, debugLanguage: 'GLSL' } );
		attachDebug( guide, { name: 'object' } );
		guide.webGLRenderer.debug.getShaderAsync.mockResolvedValue( { fragmentShader: 'glsl-frag' } );

		manager.updateDebugWGSL();
		await flushAsync();

		expect( guide.webGLRenderer.debug.getShaderAsync ).toHaveBeenCalled();
		expect( guide.renderer.debug.getShaderAsync ).not.toHaveBeenCalled();
		expect( guide.debugCodeEditor.setValue ).toHaveBeenCalledWith( 'glsl-frag' );

	} );

	test( 'reports invalid debug data when no scene or camera can be resolved', () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true, scene: null, camera: null } );
		attachDebug( guide, { name: 'object' } );

		manager.updateDebugWGSL();

		expect( guide.debugCodeEditor.setValue ).toHaveBeenCalledWith( 'Invalid debug data. Ensure scene, camera, and object are provided.' );
		expect( guide.dom.previewSection.style.height ).toBe( '100%' );

	} );

	test( 'reports when the renderer cannot provide shaders', () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true, renderer: { domElement: el( 'canvas' ) } } );
		attachDebug( guide, { name: 'object' } );

		manager.updateDebugWGSL();

		expect( guide.debugCodeEditor.setValue ).toHaveBeenCalledWith( 'WebGPURenderer debug.getShaderAsync is not available.' );

	} );

	test( 'reports shader retrieval errors', async () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		attachDebug( guide, { name: 'object' } );
		guide.renderer.debug.getShaderAsync.mockRejectedValue( new Error( 'shader boom' ) );

		manager.updateDebugWGSL();
		await flushAsync();

		expect( guide.debugCodeEditor.setValue ).toHaveBeenCalledWith( 'Error retrieving shader: shader boom' );

	} );

	test( 'restores the previous preview height once debug data is valid', async () => {

		const { guide, manager } = createManager( { isPlaygroundActive: true } );
		attachDebug( guide, { name: 'object' } );
		guide.dom.previewSection.style.height = '100%';
		guide.lastPreviewHeight = '65%';
		guide.renderer.debug.getShaderAsync.mockResolvedValue( { fragmentShader: 'frag' } );

		manager.updateDebugWGSL();
		await flushAsync();

		expect( guide.dom.previewSection.style.height ).toBe( '65%' );
		expect( guide.layoutManager.updateVResizerIcons ).toHaveBeenCalledWith( '65%' );

	} );

} );
