describe( 'PlaygroundManager.updatePlaygroundHash', () => {

	test( 'does nothing before tabs exist', async () => {

		const { guide, manager } = createManager();

		await manager.updatePlaygroundHash( true );

		expect( guide.projectsManager.autoSaveCurrentProject ).not.toHaveBeenCalled();
		expect( globalThis.history.replaceState ).not.toHaveBeenCalled();

	} );

	test( 'encodes editable tabs, records the release and replaces the url hash', async () => {

		const { guide, manager } = createManager();
		manager.playgroundTabs = [
			{ name: 'main', code: '// main\n' },
			{ name: 'helper', code: 'export {};', readOnly: true }
		];

		await manager.updatePlaygroundHash( false );

		expect( guide.projectsManager.autoSaveCurrentProject ).toHaveBeenCalledTimes( 1 );
		expect( manager.guide.lastHandledHash ).toMatch( /^playground=[A-Za-z0-9+/=]+&release=/ );
		expect( manager.guide.lastHandledHash ).toBe( 'playground=' + manager.guide.lastHandledHash.replace( /^playground=/, '' ) );
		expect( manager.guide.lastHandledHash.endsWith( '&release=' + THREE.REVISION ) ).toBe( true );

		const payload = JSON.parse( await hashTabs( manager.guide.lastHandledHash ) );
		expect( payload ).toEqual( { tabs: [ { name: 'main', code: '// main\n' } ] } );

		expect( globalThis.history.replaceState ).toHaveBeenCalledWith( null, '', '#' + manager.guide.lastHandledHash );
		expect( guide.historyManager.pushState ).not.toHaveBeenCalled();

	} );

	test( 'pushes the hash into the history when requested', async () => {

		const { guide, manager } = createManager();
		manager.playgroundTabs = [ { name: 'main', code: '// main\n' } ];

		await manager.updatePlaygroundHash( true );

		expect( guide.historyManager.pushState ).toHaveBeenCalledWith( manager.guide.lastHandledHash );

	} );

} );

